1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。任意规则节点可附布尔 nullable：
17	//   true 在原接受集合上加入 null（必填字段仍不得缺失，空正文不等于 null）；
18	//   标量节点可附非空 enum 候选数组：接受集合为“类型及可空集合”与枚举集合的
19	//   交集（可空不越过枚举；object/array 节点禁止 enum）。
20	// - 已声明 requestBody 的 POST 接口还可配置有序响应分支 branches：每支含接口内
21	//   唯一非空标识 id、非空等值条件集合 when（RFC 6901 指针 -> 字符串/有限数字/
22	//   布尔/null，支持根、对象自有字段与数组下标，保留空字段名、__proto__ 与 ~0/~1
23	//   转义）与非空响应序列 responses；接口原 responses 成为无分支命中时的兜底序列。
24	//   请求通过全部正文校验后按同一配置快照选择：指针取值不存在或无法遍历即不命中
25	//   （缺失不同于 null、不做类型转换、0 与 -0 相等），全部条件满足才命中该支；
26	//   多支命中取第一支，无命中取兜底。各分支与兜底独立计数，不改写请求字节。
27	// - 管理入口 GET /__contractlab/requests 查询本次进程内的请求记录（一致快照、
28	//   不推进序列），POST /__contractlab/requests/clear 清空记录；记录只存在内存中，
29	//   管理范围（/__contractlab 本身及 /__contractlab/ 前缀）的请求一律不记录。
30	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
31	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
32	// - import 子命令：读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面
33	//   路径”选择文档操作，仅用操作 requestBody 转换出的正文规则替换各接口的
34	//   requestBody（保留接口顺序与 responses），新场景 JSON 写 stdout。
35	// - verify 子命令：离线批量请求校验。读取 GET /__contractlab/requests 的完整
36	//   JSON 快照与一份场景配置，按输入顺序保留原编号逐条重新判定（仅依据记录中的
37	//   原始请求重新计算，不信任原版本、匹配/校验结论、计划响应与发送状态）；
38	//   报告写 stdout，不监听、不发送请求、不修改文件。
39	// - replay 子命令：本机请求重放与响应差异报告。读取同一份请求记录快照，
40	//   按输入顺序把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口
41	//   （每条只尝试一次、不跟随重定向、每条有覆盖完整收发的总超时），
42	//   仅比较实际响应的状态码与正文和记录中的计划响应；可选 --strategy
43	//   比较策略按“方法 + 字面路径”为接口选择正文 JSON 语义比较（忽略键序、
44	//   排版与指定的 RFC 6901 忽略指针），未选中的接口仍按原始字节比较；
45	//   报告写 stdout，不监听、不修改文件。
46	
47	import http from 'node:http';
48	import { readFile } from 'node:fs/promises';
49	import path from 'node:path';
50	
51	const APP_NAME = 'contractlab';
52	
53	// 管理入口（保留前缀，业务接口不得使用）
54	const ADMIN_PREFIX = '/__contractlab/';
55	const ADMIN_BASE = '/__contractlab';
56	const HEALTH_PATH = '/__contractlab/health';
57	const RELOAD_PATH = '/__contractlab/reload';
58	const REQUESTS_PATH = '/__contractlab/requests';
59	const REQUESTS_CLEAR_PATH = '/__contractlab/requests/clear';
60	
61	// 每个业务响应都携带当前配置版本
62	const VERSION_HEADER = 'X-Contractlab-Version';
63	
64	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
65	const MAX_BODY_BYTES = 100 * 1024 * 1024;
66	
67	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
68	const BLOCKED_HEADERS = new Set([
69	  'connection',
70	  'keep-alive',
71	  'content-length',
72	  'transfer-encoding',
73	]);
74	
75	// RFC 7230 token：合法的 HTTP 头名称字符
76	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
77	
78	type HttpMethod = 'GET' | 'POST';
79	
80	// ---------------------------------------------------------------------------
81	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
82	// ---------------------------------------------------------------------------
83	//
84	// 规则格式（JSON 对象，未知字段一律拒绝）：
85	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
86	//   { "type": "array", "items": <规则> }
87	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
88	// 任意规则节点（根、字段、数组元素）可附布尔 "nullable"：省略或 false 行为不变，
89	// true 在原接受集合上加入 null（type:null 本就只接受 null）。必填字段即使可空也
90	// 不能缺失；null 被接受时不产生子节点差异，非 null 值仍须通过全部原约束。
91	// 标量节点（string/number/integer/boolean/null）可附非空 "enum" 候选数组：
92	// 每项须符合节点类型与可空约定（null 项要求 nullable:true 或 type:null），
93	// 顺序与重复值不影响语义（数字按数值相等，0 与 -0 等价，不做类型转换）；
94	// 有 enum 时接受集合为“类型及可空集合”与枚举集合的交集（可空不越过枚举）。
95	// object / array 节点禁止 enum。
96	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
97	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
98	// array 必须声明 items。
99	
100	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
101	
102	// 枚举候选值：标量字面量（含 null，仅当节点可空或 type:null 时允许）
103	type EnumValue = string | number | boolean | null;
104	
105	type BodyRule =
106	  | {
107	      readonly kind: 'object';
108	      readonly fields: ReadonlyMap<string, FieldRule>;
109	      readonly additionalProperties: boolean;
110	      readonly nullable: boolean;
111	    }
112	  | { readonly kind: 'array'; readonly items: BodyRule; readonly nullable: boolean }
113	  | {
114	      readonly kind: ScalarKind;
115	      readonly nullable: boolean;
116	      // 非空候选数组（已按数值相等去重）；undefined 表示无枚举限制
117	      readonly enum: readonly EnumValue[] | undefined;
118	    };
119	
120	interface FieldRule {
121	  readonly rule: BodyRule;
122	  readonly required: boolean;
123	}
124	
125	// ---------------------------------------------------------------------------
126	// 按请求正文值选择的响应分支（endpoints[].branches，仅 POST 且声明 requestBody）
127	// ---------------------------------------------------------------------------
128	//
129	// 每个分支：
130	//   { "id": "<接口内唯一非空标识>",
131	//     "when": { "<RFC 6901 指针>": <等值条件值>, ... },   // 非空对象、至少一条
132	//     "responses": [ <非空响应序列> ] }
133	// 条件值只能是字符串、有限数字、布尔或 null；指针支持根（""）、对象自有字段
134	// （含空字段名与 "__proto__"）与数组下标，遵循 ~0/~1 转义。分支有序：全部条件
135	// 满足即命中该支，多支命中取第一支，均不命中时使用接口 responses 兜底序列。
136	
137	type BranchConditionValue = string | number | boolean | null;
138	
139	interface BranchCondition {
140	  // 原始指针串（RFC 6901），用于记录与错误定位
141	  readonly pointer: string;
142	  // 已解码的指针段（根指针为空数组）
143	  readonly segments: readonly string[];
144	  readonly value: BranchConditionValue;
145	}
146	
147	interface BranchSpec {
148	  readonly id: string;
149	  readonly conditions: readonly BranchCondition[];
150	  readonly responses: readonly ResponseSpec[];
151	}
152	
153	interface ResponseSpec {
154	  readonly status: number;
155	  readonly headers: { readonly [name: string]: string };
156	  readonly body: string;
157	  readonly delay: number;
158	}
159	
160	interface EndpointSpec {
161	  readonly method: HttpMethod;
162	  readonly path: string;
163	  // 兜底响应序列（无分支命中时使用）
164	  readonly responses: readonly ResponseSpec[];
165	  readonly bodyRule: BodyRule | undefined;
166	  // 有序分支；仅当 bodyRule 存在时非空
167	  readonly branches: readonly BranchSpec[];
168	}
169	
170	interface LiveBranch {
171	  readonly id: string;
172	  readonly conditions: readonly BranchCondition[];
173	  readonly responses: readonly ResponseSpec[];
174	  // 下一个待预留位置；到达末项后停在末项（持续复用）
175	  cursor: number;
176	}
177	
178	interface LiveEndpoint {
179	  readonly key: string;
180	  // 兜底序列
181	  readonly responses: readonly ResponseSpec[];
182	  readonly bodyRule: BodyRule | undefined;
183	  readonly branches: readonly LiveBranch[];
184	  // 兜底序列的下一个待预留位置
185	  cursor: number;
186	}
187	
188	interface LiveState {
189	  readonly version: number;
190	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
191	}
192	
193	interface ReloadResult {
194	  ok: boolean;
195	  version: number;
196	  error?: string;
197	}
198	
199	class ConfigError extends Error {
200	  constructor(message: string) {
201	    super(message);
202	    this.name = 'ConfigError';
203	  }
204	}
205	
206	// ---------------------------------------------------------------------------
207	// 配置校验
208	// ---------------------------------------------------------------------------
209	
210	function isPlainObject(value: unknown): value is Record<string, unknown> {
211	  return typeof value === 'object' && value !== null && !Array.isArray(value);
212	}
213	
214	function validatePath(p: string, where: string): void {
215	  if (p.length === 0 || p[0] !== '/') {
216	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
217	  }
218	  if (p.length > 4096) {
219	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
220	  }
221	  for (const ch of p) {
222	    const code = ch.charCodeAt(0);
223	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
224	      throw new ConfigError(
225	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
226	      );
227	    }
228	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
229	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
230	    }
231	  }
232	}
233	
234	function validateResponse(raw: unknown, where: string): ResponseSpec {
235	  if (!isPlainObject(raw)) {
236	    throw new ConfigError(`${where} 必须是对象`);
237	  }
238	  for (const key of Object.keys(raw)) {
239	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
240	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
241	    }
242	  }
243	
244	  const { status, headers, body, delay } = raw;
245	
246	  if (!Number.isInteger(status) || status < 200 || status > 599) {
247	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
248	  }
249	
250	  if (!isPlainObject(headers)) {
251	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
252	  }
253	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
254	  const cleanHeaders: { [name: string]: string } = Object.create(null);
255	  const seenNames = new Set<string>();
256	  for (const [name, value] of Object.entries(headers)) {
257	    const whereHeader = `${where}.headers["${name}"]`;
258	    if (!HEADER_NAME_RE.test(name)) {
259	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
260	    }
261	    const lower = name.toLowerCase();
262	    if (BLOCKED_HEADERS.has(lower)) {
263	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
264	    }
265	    if (seenNames.has(lower)) {
266	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
267	    }
268	    if (typeof value !== 'string') {
269	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
270	    }
271	    for (let i = 0; i < value.length; i += 1) {
272	      const code = value.charCodeAt(i);
273	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
274	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
275	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
276	        throw new ConfigError(
277	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
278	        );
279	      }
280	    }
281	    seenNames.add(lower);
282	    cleanHeaders[name] = value;
283	  }
284	
285	  if (typeof body !== 'string') {
286	    throw new ConfigError(`${where}.body 必须是文本字符串`);
287	  }
288	  if ((status === 204 || status === 304) && body !== '') {
289	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
290	  }
291	
292	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
293	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
294	  }
295	
296	  return { status, headers: cleanHeaders, body, delay };
297	}
298	
299	const SCALAR_KINDS: ReadonlySet<string> = new Set([
300	  'string',
301	  'number',
302	  'integer',
303	  'boolean',
304	  'null',
305	]);
306	
307	// 枚举项是否满足节点类型（不做类型转换；number 限有限数字、integer 限整数）
308	function enumItemConforms(kind: ScalarKind, item: unknown): boolean {
309	  switch (kind) {
310	    case 'string':
311	      return typeof item === 'string';
312	    case 'number':
313	      return typeof item === 'number' && Number.isFinite(item);
314	    case 'integer':
315	      return Number.isInteger(item);
316	    case 'boolean':
317	      return typeof item === 'boolean';
318	    case 'null':
319	      return item === null;
320	  }
321	}
322	
323	// 校验并规范化枚举候选（场景配置与 OpenAPI 导入共用语义）：非空数组、逐项符合
324	// 节点类型与可空约定（null 项要求 nullable:true 或 type:null）、按数值相等去重
325	// （0 与 -0 等价；顺序与重复值不影响语义）。失败返回可定位的 where 与原因。
326	function enumValuesOrError(
327	  enumRaw: unknown,
328	  kind: ScalarKind,
329	  nullable: boolean,
330	  where: string,
331	): { errorWhere: string; message: string } | { values: EnumValue[] } {
332	  if (!Array.isArray(enumRaw) || enumRaw.length === 0) {
333	    return { errorWhere: where, message: '必须是非空数组（至少一个候选值）' };
334	  }
335	  // Set 按 SameValueZero 去重：0 与 -0 视为同一候选
336	  const seen = new Set<unknown>();
337	  const values: EnumValue[] = [];
338	  for (let i = 0; i < enumRaw.length; i += 1) {
339	    const item = enumRaw[i];
340	    const itemWhere = `${where}[${i}]`;
341	    if (item === null) {
342	      if (!nullable && kind !== 'null') {
343	        return {
344	          errorWhere: itemWhere,
345	          message: '为 null：接受 null 要求节点为 nullable:true 或 type:"null"',
346	        };
347	      }
348	    } else if (!enumItemConforms(kind, item)) {
349	      return {
350	        errorWhere: itemWhere,
351	        message: `必须是 ${kind}（与节点类型一致，不做类型转换），收到 ${JSON.stringify(item)}`,
352	      };
353	    }
354	    if (!seen.has(item)) {
355	      seen.add(item);
356	      values.push(item as EnumValue);
357	    }
358	  }
359	  return { values };
360	}
361	
362	function validateBodyRule(raw: unknown, where: string): BodyRule {
363	  if (!isPlainObject(raw)) {
364	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
365	  }
366	
367	  const type = raw.type;
368	  const allowed = new Set(['type', 'nullable']);
369	  if (type === 'object') {
370	    allowed.add('fields');
371	    allowed.add('additionalProperties');
372	  } else if (type === 'array') {
373	    allowed.add('items');
374	  } else if (!SCALAR_KINDS.has(type as string)) {
375	    throw new ConfigError(
376	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
377	    );
378	  } else {
379	    // enum 仅允许在标量节点上；object / array 节点声明 enum 按未知字段拒绝
380	    allowed.add('enum');
381	  }
382	  for (const key of Object.keys(raw)) {
383	    if (!allowed.has(key)) {
384	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
385	    }
386	  }
387	
388	  // 任意规则节点可附布尔 nullable：省略或 false 不变，true 在原接受集合上加入 null
389	  const nullableRaw = raw.nullable;
390	  if (nullableRaw !== undefined && typeof nullableRaw !== 'boolean') {
391	    throw new ConfigError(`${where}.nullable 必须是布尔值，收到 ${JSON.stringify(nullableRaw)}`);
392	  }
393	  const nullable = nullableRaw === true;
394	
395	  // 标量节点可附非空 enum：每项须符合节点类型与可空约定；有枚举时接受集合为
396	  // “类型及可空集合”与枚举集合的交集（可空不越过枚举，null 须列入枚举才被接受）
397	  let enumValues: readonly EnumValue[] | undefined;
398	  if (raw.enum !== undefined) {
399	    const result = enumValuesOrError(raw.enum, type as ScalarKind, nullable, `${where}.enum`);
400	    if ('errorWhere' in result) {
401	      throw new ConfigError(`${result.errorWhere} ${result.message}`);
402	    }
403	    enumValues = result.values;
404	  }
405	
406	  if (type === 'object') {
407	    const fieldsRaw = raw.fields;
408	    const fields = new Map<string, FieldRule>();
409	    if (fieldsRaw !== undefined) {
410	      if (!isPlainObject(fieldsRaw)) {
411	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
412	      }
413	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
414	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
415	      }
416	    }
417	    const additional = raw.additionalProperties;
418	    if (additional !== undefined && typeof additional !== 'boolean') {
419	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
420	    }
421	    // 未声明字段默认拒绝
422	    return { kind: 'object', fields, additionalProperties: additional === true, nullable };
423	  }
424	
425	  if (type === 'array') {
426	    if (raw.items === undefined) {
427	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
428	    }
429	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`), nullable };
430	  }
431	
432	  return { kind: type as ScalarKind, nullable, enum: enumValues };
433	}
434	
435	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
436	function validateFieldRule(raw: unknown, where: string): FieldRule {
437	  if (!isPlainObject(raw)) {
438	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
439	  }
440	  let required = false;
441	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
442	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
443	  const rest: Record<string, unknown> = Object.create(null);
444	  for (const [key, value] of Object.entries(raw)) {
445	    if (key === 'required') {
446	      if (typeof value !== 'boolean') {
447	        throw new ConfigError(`${where}.required 必须是布尔值`);
448	      }
449	      required = value;
450	    } else {
451	      rest[key] = value;
452	    }
453	  }
454	  return { rule: validateBodyRule(rest, where), required };
455	}
456	
457	// RFC 6901 JSON Pointer 语法解析："" 表示根（零段）；否则必须以 "/" 开头，
458	// 按 "/" 分段并反转义（~1 -> "/"，~0 -> "~"，先处理 ~1 以免二次转义）。
459	// 段内出现不以 0/1 收尾的 "~" 属非法指针。这里只判定语法；段能否在具体 JSON
460	// 值上遍历（对象自有字段、数组下标）由运行时选择逻辑判定。
461	// label 用于错误信息中对指针用途的称呼（分支条件键 / 忽略指针）。
462	function parseJsonPointer(raw: unknown, where: string, label = '条件键'): string[] {
463	  if (typeof raw !== 'string') {
464	    throw new ConfigError(`${where} 的${label}必须是 RFC 6901 指针字符串，收到 ${JSON.stringify(raw)}`);
465	  }
466	  if (raw === '') {
467	    return [];
468	  }
469	  if (raw[0] !== '/') {
470	    throw new ConfigError(
471	      `${where} 的指针 ${JSON.stringify(raw)} 非法：非根指针必须以 "/" 开头（根指针为 ""）`,
472	    );
473	  }
474	  return raw.slice(1).split('/').map((segment, i) => {
475	    let out = '';
476	    for (let j = 0; j < segment.length; j += 1) {
477	      const ch = segment[j];
478	      if (ch === '~') {
479	        const next = segment[j + 1];
480	        if (next === '0') {
481	          out += '~';
482	          j += 1;
483	        } else if (next === '1') {
484	          out += '/';
485	          j += 1;
486	        } else {
487	          throw new ConfigError(
488	            `${where} 的指针 ${JSON.stringify(raw)} 非法：第 ${i} 段含非法转义（仅支持 ~0 与 ~1）`,
489	          );
490	        }
491	      } else {
492	        out += ch;
493	      }
494	    }
495	    return out;
496	  });
497	}
498	
499	// 等值条件值：字符串、有限数字、布尔或 null（不接受 NaN/Infinity、对象、数组）
500	function validateConditionValue(raw: unknown, where: string): BranchConditionValue {
501	  if (raw === null) {
502	    return null;
503	  }
504	  if (typeof raw === 'string' || typeof raw === 'boolean') {
505	    return raw;
506	  }
507	  if (typeof raw === 'number') {
508	    if (!Number.isFinite(raw)) {
509	      throw new ConfigError(
510	        `${where} 的条件值必须是有限数字，收到 ${JSON.stringify(raw)}`,
511	      );
512	    }
513	    return raw;
514	  }
515	  throw new ConfigError(
516	    `${where} 的条件值必须是字符串、有限数字、布尔或 null，收到 ${JSON.stringify(raw)}`,
517	  );
518	}
519	
520	function validateBranch(raw: unknown, endpointWhere: string, index: number, seenIds: Set<string>): BranchSpec {
521	  const where = `${endpointWhere}.branches[${index}]`;
522	  if (!isPlainObject(raw)) {
523	    throw new ConfigError(`${where} 必须是对象`);
524	  }
525	  for (const key of Object.keys(raw)) {
526	    if (key !== 'id' && key !== 'when' && key !== 'responses') {
527	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
528	    }
529	  }
530	
531	  const { id, when, responses } = raw;
532	
533	  if (typeof id !== 'string' || id === '') {
534	    throw new ConfigError(`${where}.id 必须是非空字符串，收到 ${JSON.stringify(id)}`);
535	  }
536	  if (seenIds.has(id as string)) {
537	    throw new ConfigError(`${where}.id ${JSON.stringify(id)} 与同一接口的其他分支标识重复`);
538	  }
539	  seenIds.add(id as string);
540	
541	  if (!isPlainObject(when)) {
542	    throw new ConfigError(`${where}.when 必须是“指针 -> 条件值”的非空对象`);
543	  }
544	  // JSON.parse 以 CreateDataProperty 写入，名为 "__proto__" 的条件键仍是自有字段
545	  const entries = Object.entries(when);
546	  if (entries.length === 0) {
547	    throw new ConfigError(`${where}.when 必须至少包含一条等值条件`);
548	  }
549	  const conditions: BranchCondition[] = entries.map(([pointer, valueRaw]) => {
550	    const condWhere = `${where}.when[${JSON.stringify(pointer)}]`;
551	    const segments = parseJsonPointer(pointer, condWhere);
552	    const value = validateConditionValue(valueRaw, condWhere);
553	    return { pointer, segments, value };
554	  });
555	
556	  if (!Array.isArray(responses) || responses.length === 0) {
557	    throw new ConfigError(`${where}.responses 必须是非空数组`);
558	  }
559	  const cleanResponses = responses.map((item, j) =>
560	    validateResponse(item, `${where}.responses[${j}]`),
561	  );
562	
563	  return { id: id as string, conditions, responses: cleanResponses };
564	}
565	
566	function validateEndpoint(
567	  raw: unknown,
568	  index: number,
569	  seen: Set<string>,
570	): EndpointSpec {
571	  const where = `endpoints[${index}]`;
572	  if (!isPlainObject(raw)) {
573	    throw new ConfigError(`${where} 必须是对象`);
574	  }
575	  for (const key of Object.keys(raw)) {
576	    if (
577	      key !== 'method' &&
578	      key !== 'path' &&
579	      key !== 'responses' &&
580	      key !== 'requestBody' &&
581	      key !== 'branches'
582	    ) {
583	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
584	    }
585	  }
586	
587	  const { method, path: routePath, responses, requestBody, branches: branchesRaw } = raw;
588	
589	  if (method !== 'GET' && method !== 'POST') {
590	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
591	  }
592	
593	  if (typeof routePath !== 'string') {
594	    throw new ConfigError(`${where}.path 必须是字符串`);
595	  }
596	  validatePath(routePath, where);
597	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
598	    throw new ConfigError(
599	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
600	    );
601	  }
602	
603	  const key = `${method} ${routePath}`;
604	  if (seen.has(key)) {
605	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
606	  }
607	  seen.add(key);
608	
609	  if (!Array.isArray(responses) || responses.length === 0) {
610	    throw new ConfigError(`${where}.responses 必须是非空数组`);
611	  }
612	  const cleanResponses = responses.map((item, j) =>
613	    validateResponse(item, `${where}.responses[${j}]`),
614	  );
615	
616	  let bodyRule: BodyRule | undefined;
617	  if (requestBody !== undefined) {
618	    if (method !== 'POST') {
619	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
620	    }
621	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
622	  }
623	
624	  let branches: readonly BranchSpec[] = [];
625	  if (branchesRaw !== undefined) {
626	    // 分支以正文值为条件：GET 接口与未声明 requestBody 的 POST 接口一律禁止
627	    if (method !== 'POST') {
628	      throw new ConfigError(`${where}.branches 仅允许在 POST 接口上声明（GET 接口不允许配置响应分支）`);
629	    }
630	    if (!bodyRule) {
631	      throw new ConfigError(
632	        `${where}.branches 仅允许在声明了 requestBody 的 POST 接口上配置：按正文值选择分支必须先声明正文规则`,
633	      );
634	    }
635	    if (!Array.isArray(branchesRaw) || branchesRaw.length === 0) {
636	      throw new ConfigError(`${where}.branches 必须是非空数组`);
637	    }
638	    const seenIds = new Set<string>();
639	    branches = branchesRaw.map((branch, j) => validateBranch(branch, where, j, seenIds));
640	  }
641	
642	  return { method, path: routePath, responses: cleanResponses, bodyRule, branches };
643	}
644	
645	function validateConfig(raw: unknown): EndpointSpec[] {
646	  if (!isPlainObject(raw)) {
647	    throw new ConfigError('配置顶层必须是 JSON 对象');
648	  }
649	  for (const key of Object.keys(raw)) {
650	    if (key !== 'endpoints') {
651	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
652	    }
653	  }
654	  const list = raw.endpoints;
655	  if (!Array.isArray(list) || list.length === 0) {
656	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
657	  }
658	  const seen = new Set<string>();
659	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
660	}
