664	// ---------------------------------------------------------------------------
665	
666	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
667	  const endpoints = new Map<string, LiveEndpoint>();
668	  for (const spec of specs) {
669	    endpoints.set(`${spec.method} ${spec.path}`, {
670	      key: `${spec.method} ${spec.path}`,
671	      responses: spec.responses,
672	      bodyRule: spec.bodyRule,
673	      branches: spec.branches.map((branch) => ({
674	        id: branch.id,
675	        conditions: branch.conditions,
676	        responses: branch.responses,
677	        cursor: 0,
678	      })),
679	      cursor: 0,
680	    });
681	  }
682	  return { version, endpoints };
683	}
