685	// 一个可选序列的预留结果：分支命中时为该支序列，否则为接口兜底序列
686	interface ReservedResponse {
687	  readonly position: number;
688	  readonly item: ResponseSpec;
689	  // 命中的分支标识；null 表示兜底
690	  readonly branchId: string | null;
691	  // 选中序列（用于记录 sequenceLength）
692	  readonly sequence: readonly ResponseSpec[];
693	}
694	
695	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
696	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
697	// 返回本次消费位置（0 起）与该项；末项复用时位置停在 length-1。
698	function reserveFromSequence(
699	  responses: readonly ResponseSpec[],
700	  cursorRef: { cursor: number },
701	): { position: number; item: ResponseSpec } {
702	  const last = responses.length - 1;
703	  const position = cursorRef.cursor < last ? cursorRef.cursor : last;
704	  if (cursorRef.cursor < last) {
705	    cursorRef.cursor += 1;
706	  }
707	  return { position, item: responses[position] };
708	}
709	
710	// 按 RFC 6901 段在已解析 JSON 值上取值：
711	// - 零段（根指针 ""）返回根值；
712	// - 对象按自有字段（hasOwnProperty）取，空字段名与 "__proto__" 一样是普通字段；
713	// - 数组按下标取（"0" 或非零开头的十进制整数，且在长度范围内；"-" 越界不命中）；
714	// - 字段缺失、下标越界或需要在标量/null 上继续遍历时，返回 undefined 表示
715	//   “无法取到值”。调用方据此判定不命中——缺失与显式 null 必须区分。
716	function resolvePointer(root: unknown, segments: readonly string[]): unknown {
717	  let current: unknown = root;
718	  for (const segment of segments) {
719	    if (Array.isArray(current)) {
720	      if (!/^(0|[1-9]\d*)$/.test(segment)) {
721	        return undefined;
722	      }
723	      const index = Number(segment);
724	      if (index >= current.length) {
725	        return undefined;
726	      }
727	      current = current[index];
728	    } else if (isPlainObject(current)) {
729	      if (!Object.prototype.hasOwnProperty.call(current, segment)) {
730	        return undefined;
731	      }
732	      current = current[segment];
733	    } else {
734	      // 在 null / 字符串 / 数字 / 布尔上无法继续遍历
735	      return undefined;
736	    }
737	  }
738	  return current;
739	}
740	
741	// 等值匹配：严格相等、不做类型转换；=== 下数字 0 与 -0 本就相等。
742	// 取不到值（undefined）永不等于任何条件值，故显式 null 条件不会命中缺失字段。
743	function conditionMatches(root: unknown, condition: BranchCondition): boolean {
744	  const actual = resolvePointer(root, condition.segments);
745	  return actual !== undefined && actual === condition.value;
746	}
747	
748	// 一支的全部条件都满足才命中
749	function branchMatches(branch: LiveBranch, parsedBody: unknown): boolean {
750	  for (const condition of branch.conditions) {
751	    if (!conditionMatches(parsedBody, condition)) {
752	      return false;
753	    }
754	  }
755	  return true;
756	}
757	
758	// 根据正文值选择分支（首支命中）并从该支或兜底序列预留下一项
759	function reserveForBody(endpoint: LiveEndpoint, parsedBody: unknown): ReservedResponse {
760	  for (const branch of endpoint.branches) {
761	    if (branchMatches(branch, parsedBody)) {
762	      const { position, item } = reserveFromSequence(branch.responses, branch);
763	      return { position, item, branchId: branch.id, sequence: branch.responses };
764	    }
765	  }
766	  const { position, item } = reserveFromSequence(endpoint.responses, endpoint);
767	  return { position, item, branchId: null, sequence: endpoint.responses };
768	}
