770	// ---------------------------------------------------------------------------
771	// 进程内请求记录
772	// ---------------------------------------------------------------------------
773	//
774	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
775	// 未收完整即断开或超出上限不创建记录、不消费序列。
776	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
777	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
778	
779	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
780	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
781	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
782	//   interrupted —— 写出完成前连接断开或写入/发送失败
783	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
784	
785	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
786	interface PlannedResponseSnapshot {
787	  readonly kind: 'scene' | 'framework';
788	  readonly status: number;
789	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
790	  readonly headers: { readonly [name: string]: string };
791	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
792	  readonly body: string;
793	}
794	
795	interface RequestRecord {
796	  readonly id: number;
797	  readonly receivedAt: string;
798	  readonly request: {
799	    readonly method: string;
800	    // 含查询串的原始请求目标
801	    readonly target: string;
802	    readonly path: string;
803	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
804	    readonly rawHeaders: readonly string[];
805	    readonly bodyBytes: number;
806	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
807	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
808	  };
809	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
810	  configVersion: number;
811	  // matched=false：未匹配（404），不消费任何序列
812	  matched: boolean;
813	  endpoint: string | null;
814	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
815	  bodyValidationPassed: boolean | null;
816	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
817	  bodyRejection: BodyReport | null;
818	  // 场景请求的分支选择：
819	  //   null                 —— 未选择（400/404，或无分支的场景请求之外的情形）；
820	  //   { kind:'fallback' }  —— 无分支命中，使用接口兜底 responses；
821	  //   { kind:'branch', id }—— 命中指定分支，使用该支 responses。
822	  // 无分支接口的场景请求记为 fallback。
823	  branchSelection: { readonly kind: 'branch'; readonly id: string } | { readonly kind: 'fallback' } | null;
824	  // 场景请求在“选中序列”中的消费位置（0 起）；400/404 没有消费位置，记为 null
825	  sequencePosition: number | null;
826	  // 选中序列（命中分支或兜底）的长度；400/404 为 null
827	  sequenceLength: number | null;
828	  plannedResponse: PlannedResponseSnapshot | null;
829	  delivery: DeliveryStatus;
830	}
