832	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
833	class RequestLog {
834	  private records: RequestRecord[] = [];
835	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
836	  private readonly live = new Map<number, RequestRecord>();
837	  private nextId = 1;
838	
839	  create(entry: {
840	    method: string;
841	    target: string;
842	    path: string;
843	    rawHeaders: readonly string[];
844	    body: Buffer;
845	    configVersion: number;
846	  }): RequestRecord {
847	    const id = this.nextId;
848	    this.nextId += 1;
849	    const record: RequestRecord = {
850	      id,
851	      receivedAt: new Date().toISOString(),
852	      request: {
853	        method: entry.method,
854	        target: entry.target,
855	        path: entry.path,
856	        rawHeaders: entry.rawHeaders,
857	        bodyBytes: entry.body.byteLength,
858	        body: encodeBodyLosslessly(entry.body),
859	      },
860	      configVersion: entry.configVersion,
861	      matched: false,
862	      endpoint: null,
863	      bodyValidationPassed: null,
864	      bodyRejection: null,
865	      branchSelection: null,
866	      sequencePosition: null,
867	      sequenceLength: null,
868	      plannedResponse: null,
869	      delivery: 'pending',
870	    };
871	    this.records.push(record);
872	    this.live.set(id, record);
873	    return record;
874	  }
875	
876	  // 写出完成；对已清空（不再存活）的记录是 no-op
877	  markDelivered(id: number, status: DeliveryStatus): void {
878	    const record = this.live.get(id);
879	    if (!record) {
880	      return;
881	    }
882	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
883	    if (record.delivery === 'sent') {
884	      return;
885	    }
886	    record.delivery = status;
887	  }
888	
889	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
890	  snapshot(): readonly RequestRecord[] {
891	    return [...this.records];
892	  }
893	
894	  // 清空一次移除当时全部记录（含待发送项）；不取消响应、不改配置/版本/序列。
895	  // 清空前已完整接收的请求随后完成或失败都不再出现。
896	  clear(): number {
897	    const removed = this.records.length;
898	    this.records = [];
899	    this.live.clear();
900	    return removed;
901	  }
902	}
903	
904	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
905	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
906	// ignoreBOM：开头 BOM（EF BB BF）必须保留在文本中（默认行为会将其丢弃），
907	// 否则文本重新编码回不去原始字节，快照就不再无损。
908	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
909	  try {
910	    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body);
911	    return { encoding: 'utf-8', content: text };
912	  } catch {
913	    return { encoding: 'base64', content: body.toString('base64') };
914	  }
915	}
