917	// ---------------------------------------------------------------------------
918	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
919	// ---------------------------------------------------------------------------
920	
921	interface StructureProblem {
922	  readonly pointer: string;
923	  readonly expected: string;
924	  readonly actual: string;
925	}
926	
927	interface BodyReport {
928	  readonly error: 'invalid_request_body';
929	  readonly stage: 'parse' | 'structure';
930	  readonly message: string;
931	  readonly problems: readonly StructureProblem[];
932	}
933	
934	function parseFailure(message: string): BodyReport {
935	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
936	}
937	
938	function jsonTypeOf(value: unknown): string {
939	  if (value === null) {
940	    return 'null';
941	  }
942	  if (Array.isArray(value)) {
943	    return 'array';
944	  }
945	  return typeof value;
946	}
947	
948	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
949	function escapePointerSegment(segment: string): string {
950	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
951	}
952	
953	// 枚举差异的期望描述：列全候选值（JSON 形式，数字 0 与 -0 都写作 0）
954	function enumExpectedText(enumValues: readonly EnumValue[]): string {
955	  return `枚举 ${JSON.stringify(enumValues)} 之一`;
956	}
957	
958	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
959	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
960	// 可空规则：null 被接受时不产生任何子节点差异；非 null 继续检查全部原约束。
961	// 枚举规则：接受集合为“类型及可空集合”与枚举集合的交集——可空不越过枚举
962	// （null 须列入枚举才被接受）；类型错误只报类型差异，不重复报枚举差异。
963	function checkRule(
964	  rule: BodyRule,
965	  value: unknown,
966	  pointer: string,
967	  problems: StructureProblem[],
968	): void {
969	  if (value === null && rule.nullable) {
970	    // 可空不越过枚举：有枚举时 null 仍须在候选集合中
971	    if (rule.kind === 'object' || rule.kind === 'array') {
972	      return;
973	    }
974	    if (rule.enum === undefined || rule.enum.includes(null)) {
975	      return;
976	    }
977	    problems.push({ pointer, expected: enumExpectedText(rule.enum), actual: 'null' });
978	    return;
979	  }
980	  switch (rule.kind) {
981	    case 'string':
982	    case 'boolean':
983	      if (typeof value !== rule.kind) {
984	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
985	        return;
986	      }
987	      break;
988	    case 'null':
989	      if (value !== null) {
990	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
991	      }
992	      return;
993	    case 'number':
994	      if (typeof value !== 'number' || !Number.isFinite(value)) {
995	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
996	        return;
997	      }
998	      break;
999	    case 'integer':
1000	      if (!Number.isInteger(value)) {
1001	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
1002	        return;
1003	      }
1004	      break;
1005	    case 'array': {
1006	      if (!Array.isArray(value)) {
1007	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
1008	        return;
1009	      }
1010	      for (let i = 0; i < value.length; i += 1) {
1011	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
1012	      }
1013	      return;
1014	    }
1015	    case 'object': {
1016	      if (!isPlainObject(value)) {
1017	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
1018	        return;
1019	      }
1020	      for (const [name, field] of rule.fields) {
1021	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
1022	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
1023	          if (field.required) {
1024	            problems.push({
1025	              pointer: childPointer,
1026	              expected: `${field.rule.kind}（必填字段）`,
1027	              actual: 'missing',
1028	            });
1029	          }
1030	        } else {
1031	          checkRule(field.rule, value[name], childPointer, problems);
1032	        }
1033	      }
1034	      if (!rule.additionalProperties) {
1035	        for (const key of Object.keys(value)) {
1036	          if (!rule.fields.has(key)) {
1037	            problems.push({
1038	              pointer: `${pointer}/${escapePointerSegment(key)}`,
1039	              expected: '未声明的字段（不允许）',
1040	              actual: jsonTypeOf(value[key]),
1041	            });
1042	          }
1043	        }
1044	      }
1045	      return;
1046	    }
1047	  }
1048	  // 标量枚举：类型检查已通过才核对候选集合（类型错误不重复报枚举错误）；
1049	  // 数字按数值相等（0 与 -0 等价），不做类型转换
1050	  if (rule.enum !== undefined && !rule.enum.includes(value as EnumValue)) {
1051	    problems.push({
1052	      pointer,
1053	      expected: enumExpectedText(rule.enum),
1054	      actual: JSON.stringify(value),
1055	    });
1056	  }
1057	}
