1059	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
1060	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
1061	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
1062	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
1063	// 在线与离线对同一组字节给出同一结论。
1064	// 通过时经 parseBodyOnly 另行解析以取得分支选择所用的 JSON 值。
1065	function validateBodyWithContentType(
1066	  contentType: string | undefined,
1067	  body: Buffer,
1068	  rule: BodyRule,
1069	): BodyReport | null {
1070	  const parsed = parseJsonBodyForCheck(contentType, body);
1071	  if ('report' in parsed) {
1072	    return parsed.report;
1073	  }
1074	  const problems: StructureProblem[] = [];
1075	  checkRule(rule, parsed.value, '', problems);
1076	  if (problems.length > 0) {
1077	    return {
1078	      error: 'invalid_request_body',
1079	      stage: 'structure',
1080	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
1081	      problems,
1082	    };
1083	  }
1084	  return null;
1085	}
