1087	// 媒体类型 -> UTF-8 -> JSON 解析：通过返回 { value }，否则返回 { report }。
1088	// 在线（分支选择）与离线需要同一解析结论，故抽出共用。
1089	function parseJsonBodyForCheck(
1090	  contentType: string | undefined,
1091	  body: Buffer,
1092	): { value: unknown } | { report: BodyReport } {
1093	  const mediaType =
1094	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
1095	  if (mediaType !== 'application/json') {
1096	    return {
1097	      report: parseFailure(
1098	        typeof contentType === 'string'
1099	          ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
1100	          : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
1101	      ),
1102	    };
1103	  }
1104	
1105	  if (body.length === 0) {
1106	    return { report: parseFailure('请求正文为空，无法解析为 JSON') };
1107	  }
1108	
1109	  let text: string;
1110	  try {
1111	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
1112	  } catch {
1113	    return { report: parseFailure('请求正文不是合法的 UTF-8 编码') };
1114	  }
1115	
1116	  try {
1117	    return { value: JSON.parse(text) };
1118	  } catch (e) {
1119	    return { report: parseFailure(`请求正文不是合法 JSON：${describeError(e)}`) };
1120	  }
1121	}
1122	
1123	// 在线路径：校验媒体类型/UTF-8/JSON/结构，通过时同时返回解析出的 JSON 值
1124	// （供按正文值选择响应分支使用）。
1125	function validateBodyAndParse(
1126	  contentType: string | undefined,
1127	  body: Buffer,
1128	  rule: BodyRule,
1129	): { report: BodyReport } | { value: unknown } {
1130	  const parsed = parseJsonBodyForCheck(contentType, body);
1131	  if ('report' in parsed) {
1132	    return parsed;
1133	  }
1134	  const problems: StructureProblem[] = [];
1135	  checkRule(rule, parsed.value, '', problems);
1136	  if (problems.length > 0) {
1137	    return {
1138	      report: {
1139	        error: 'invalid_request_body',
1140	        stage: 'structure',
1141	        message: `请求正文与接口约定存在 ${problems.length} 处差异`,
1142	        problems,
1143	      },
1144	    };
1145	  }
1146	  return { value: parsed.value };
1147	}
