1150	// 文件读取与（重新）加载：读、解析、校验全部通过后才一次性替换
1151	// ---------------------------------------------------------------------------
1152	
1153	function describeError(e: unknown): string {
1154	  return e instanceof Error ? e.message : String(e);
1155	}
1156	
1157	// 读取 -> 解析 -> 严格校验；任何一步失败都抛出含文件路径与可定位原因的错误
1158	async function loadSpecsFromFile(configPath: string): Promise<EndpointSpec[]> {
1159	  let text: string;
1160	  try {
1161	    text = await readFile(configPath, 'utf8');
1162	  } catch (e) {
1163	    throw new Error(`读取配置文件 ${configPath} 失败：${describeError(e)}`);
1164	  }
1165	
1166	  let raw: unknown;
1167	  try {
1168	    raw = JSON.parse(text);
1169	  } catch (e) {
1170	    throw new Error(`配置文件 ${configPath} 不是合法 JSON：${describeError(e)}`);
1171	  }
1172	
1173	  try {
1174	    return validateConfig(raw);
1175	  } catch (e) {
1176	    throw new Error(`配置文件 ${configPath} 校验失败：${describeError(e)}`);
1177	  }
1178	}
1179	
1180	async function loadStateFromFile(configPath: string, version: number): Promise<LiveState> {
1181	  return buildState(version, await loadSpecsFromFile(configPath));
1182	}
