1184	// ---------------------------------------------------------------------------
1185	// 离线兼容报告（compare 子命令）
1186	// ---------------------------------------------------------------------------
1187	//
1188	// 兼容方向固定为 旧 -> 新：旧配置能按“方法 + 字面路径”匹配且通过正文检查的
1189	// 每一种请求，在新配置中仍须匹配并通过。只比较接口存在性与请求接受条件；
1190	// 响应状态/头/正文/延迟与序列差异不影响结论。
1191	//
1192	// 双方都配置 requestBody 时，比较的是“规则所接受 JSON 值的集合包含关系”
1193	// L(旧规则) ⊆ L(新规则)，而不是文本比较或抽样请求；每个不兼容点都附一份
1194	// 具体反例（旧规则接受、新规则拒绝的完整 JSON 值）。
1195	
1196	interface ReportReason {
1197	  // 正文差异：RFC 6901 指针（根为 ""）；接口级原因（如接口删除）无此字段
1198	  readonly pointer?: string;
1199	  readonly message: string;
1200	}
1201	
1202	interface ReportExample {
1203	  readonly method: HttpMethod;
1204	  readonly path: string;
1205	  readonly headers: { readonly [name: string]: string };
1206	  readonly body: string;
1207	}
1208	
1209	interface EndpointReport {
1210	  readonly method: HttpMethod;
1211	  readonly path: string;
1212	  readonly compatible: boolean;
1213	  readonly reasons: readonly ReportReason[];
1214	  readonly example?: ReportExample;
1215	}
