1217	interface CompareReport {
1218	  readonly compatible: boolean;
1219	  readonly oldFile: string;
1220	  readonly newFile: string;
1221	  readonly endpoints: readonly EndpointReport[];
1222	}
1223	
1224	interface BodyViolation {
1225	  readonly pointer: string;
1226	  readonly message: string;
1227	  // 完整请求正文反例：被旧规则接受、被新规则拒绝
1228	  readonly value: unknown;
1229	}
