1231	// 生成被规则接受的最小 JSON 值：object 只含必填字段，array 取空数组；
1232	// 枚举节点任选一候选（优先非 null 项——“类型收紧”反例需要非 null 样本）。
1233	// 字段名可能是 "" 或 "__proto__"，一律用无原型对象按自有字段构造。
1234	function sampleValue(rule: BodyRule): unknown {
1235	  if (rule.kind !== 'object' && rule.kind !== 'array' && rule.enum !== undefined) {
1236	    const nonNull = rule.enum.find((v) => v !== null);
1237	    return nonNull === undefined ? null : nonNull;
1238	  }
1239	  switch (rule.kind) {
1240	    case 'string':
1241	      return 'contractlab';
1242	    case 'number':
1243	    case 'integer':
1244	      return 0;
1245	    case 'boolean':
1246	      return false;
1247	    case 'null':
1248	      return null;
1249	    case 'array':
1250	      return [];
1251	    case 'object': {
1252	      const obj: Record<string, unknown> = Object.create(null);
1253	      for (const [name, field] of rule.fields) {
1254	        if (field.required) {
1255	          obj[name] = sampleValue(field.rule);
1256	        }
1257	      }
1258	      return obj;
1259	    }
1260	  }
1261	}
1262	
1263	// 规则是否接受 null：type:null 或 nullable:true；有枚举时 null 还须列入候选
1264	// （可空不越过枚举）。object / array 节点没有枚举。
1265	function ruleAcceptsNullValue(rule: BodyRule): boolean {
1266	  if (!rule.nullable && rule.kind !== 'null') {
1267	    return false;
1268	  }
1269	  if (rule.kind === 'object' || rule.kind === 'array') {
1270	    return true;
1271	  }
1272	  return rule.enum === undefined || rule.enum.includes(null);
1273	}
1274	
1275	// 规则的非 null 接受集合是否非空：枚举仅含 null 项的标量规则只接受 null
1276	function hasNonNullAcceptedValues(rule: BodyRule): boolean {
1277	  if (rule.kind === 'null') {
1278	    return false;
1279	  }
1280	  if (rule.kind === 'object' || rule.kind === 'array') {
1281	    return true;
1282	  }
1283	  return rule.enum === undefined || rule.enum.some((v) => v !== null);
1284	}
