1286	// 在 object 规则的最小样本上补一个字段（字段值本身须被该字段规则接受）
1287	function sampleObjectWith(
1288	  rule: Extract<BodyRule, { kind: 'object' }>,
1289	  name: string,
1290	  value: unknown,
1291	): Record<string, unknown> {
1292	  const obj = sampleValue(rule) as Record<string, unknown>;
1293	  obj[name] = value;
1294	  return obj;
1295	}
