1297	// 生成被规则拒绝的 JSON 值（顶层类型即不符；任何规则都存在这样的值）
1298	function violateValue(rule: BodyRule): unknown {
1299	  switch (rule.kind) {
1300	    case 'number':
1301	      return 'contractlab'; // 非数字
1302	    case 'integer':
1303	      return 0.5; // 非整数
1304	    default:
1305	      return 0; // 非 string / boolean / null / object / array
1306	  }
1307	}
