1316	// 选一个两个规则都未声明的字段名，用于构造“额外字段”反例
1317	function freshFieldName(
1318	  oldFields: ReadonlyMap<string, FieldRule>,
1319	  newFields: ReadonlyMap<string, FieldRule>,
1320	): string {
1321	  for (let i = 0; ; i += 1) {
