1329	// 非 null 值是否被标量规则接受：先过类型约束，再过枚举候选（如有）
1330	function scalarValueAccepted(
1331	  rule: Extract<BodyRule, { kind: ScalarKind }>,
1332	  value: unknown,
1333	): boolean {
1334	  switch (rule.kind) {
1335	    case 'string':
