1337	        return false;
1338	      }
1339	      break;
1340	    case 'boolean':
1341	      if (typeof value !== 'boolean') {
1342	        return false;
1343	      }
1344	      break;
1345	    case 'number':
1346	      if (typeof value !== 'number' || !Number.isFinite(value)) {
1347	        return false;
1348	      }
1349	      break;
1350	    case 'integer':
1351	      if (!Number.isInteger(value)) {
1352	        return false;
1353	      }
1354	      break;
