1361	// 标量规则的简述（用于原因消息）：类型 + 枚举候选（如有）
1362	function scalarRuleLabel(rule: Extract<BodyRule, { kind: ScalarKind }>): string {
1363	  return rule.enum === undefined ? rule.kind : `${rule.kind}（${enumExpectedText(rule.enum)}）`;
1364	}
