1366	// 生成一个属于指定类型、但不在给定枚举中的值（类型取值无限，必然找得到）
1367	function freshValueOutsideEnum(
1368	  kind: 'string' | 'number' | 'integer',
1369	  enumValues: readonly EnumValue[],
1370	): string | number {
