1374	      if (!enumValues.includes(candidate)) {
1375	        return candidate;
1376	      }
1377	    }
1378	  }
1379	  for (let i = 0; ; i += 1) {
1380	    if (!enumValues.includes(i)) {
1381	      return i;
1382	    }
1383	  }
1384	}
