1386	// 标量旧规则 ⊆ 标量新规则的精确判定（双方都不是 null 类型；null 接受性已由
1387	// 调用方比较）。枚举按集合语义处理：
1388	// - 旧有枚举：旧的非 null 接受集合就是枚举的非 null 项，逐一核对新规则；
1389	// - 旧无枚举、新有枚举：旧的接受集合是整个类型取值（boolean 有限，逐一核对；
1390	//   string/number/integer 无限，构造不在新枚举中的见证值）；
1391	// - 双方均无枚举：仅同名兼容，外加 integer 放宽为 number。
1392	function collectScalarViolations(
1393	  oldRule: Extract<BodyRule, { kind: ScalarKind }>,
1394	  newRule: Extract<BodyRule, { kind: ScalarKind }>,
1395	  pointer: string,
1396	  out: BodyViolation[],
1397	): void {
1398	  if (oldRule.enum !== undefined) {
