1401	        continue; // null 的接受性已由调用方比较
1402	      }
1403	      if (!scalarValueAccepted(newRule, value)) {
1404	        out.push({
1405	          pointer,
1406	          value,
1407	          message: `枚举收紧：旧规则接受的枚举值 ${JSON.stringify(value)} 不被新规则（${scalarRuleLabel(newRule)}）接受`,
1408	        });
1409	      }
1410	    }
1411	    return;
1412	  }
1413	
1414	  if (newRule.enum !== undefined) {
1415	    // 旧规则接受整个类型集合，新规则只接受枚举候选
1416	    if (oldRule.kind === 'boolean') {
1417	      for (const value of [false, true]) {
1418	        if (!scalarValueAccepted(newRule, value)) {
1419	          out.push({
1420	            pointer,
1421	            value,
1422	            message: `新规则引入枚举限制（${enumExpectedText(newRule.enum)}），旧规则允许的值 ${JSON.stringify(value)} 不在候选中`,
1423	          });
1424	        }
1425	      }
1426	      return;
1427	    }
1428	    if (oldRule.kind === 'string' || oldRule.kind === 'number' || oldRule.kind === 'integer') {
1429	      // 类型取值无限而枚举有限：构造旧规则接受、但不在新枚举中的见证值
1430	      const witness = freshValueOutsideEnum(oldRule.kind, newRule.enum);
1431	      out.push({
1432	        pointer,
1433	        value: witness,
1434	        message: `新规则引入枚举限制（${enumExpectedText(newRule.enum)}），旧规则允许的值 ${JSON.stringify(witness)} 不在候选中`,
1435	      });
1436	      return;
1437	    }
1438	    return; // oldRule.kind === 'null' 不会到达（调用方已处理）
1439	  }
1440	
1441	  // 双方均无枚举：仅同名兼容，外加 integer 放宽为 number
1442	  const compatible =
1443	    oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
1444	  if (!compatible) {
1445	    // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
1446	    const value =
1447	      oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
1448	    out.push({
1449	      pointer,
1450	      value,
1451	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1452	    });
1453	  }
1454	}
