1456	// 递归判定 L(oldRule) ⊆ L(newRule)；把发现的每个反例（连同完整正文样本）推入 out。
1457	// 不变式：value 必被 oldRule 接受、被 newRule 拒绝；pointer 用 RFC 6901 定位差异。
1458	// 可空（nullable:true 或 type:null）规则的接受集合含 null：先单独比较 null 的
1459	// 接受性，再比较双方的非 null 部分——可空不能掩盖非 null 约束的变化。
1460	// 枚举（enum）规则按集合语义比较：接受集合为“类型及可空集合”与枚举集合的交集，
1461	// 枚举增删、枚举与非枚举规则交叉（如 number 枚举全为整数时兼容非枚举 integer）
1462	// 都精确判定；可空不越过枚举（null 须列入枚举才算被接受）。
1463	function collectViolations(
1464	  oldRule: BodyRule,
1465	  newRule: BodyRule,
1466	  pointer: string,
1467	  out: BodyViolation[],
1468	): void {
1469	  const oldAcceptsNull = ruleAcceptsNullValue(oldRule);
1470	  const newAcceptsNull = ruleAcceptsNullValue(newRule);
1471	  if (oldAcceptsNull && !newAcceptsNull) {
1472	    // null 本身就是完整反例；嵌套位置由外层调用方包上必要的父对象与必填字段
1473	    out.push({ pointer, value: null, message: '旧规则接受 null，新规则不接受 null' });
1474	  }
1475	  // type:null 的旧规则只接受 null（上面已比较），没有非 null 值需要再比
1476	  if (oldRule.kind === 'null') {
1477	    return;
1478	  }
1479	  // 枚举仅含 null 项的旧规则同样只接受 null：可比较的只有 null，上面已处理
1480	  if (!hasNonNullAcceptedValues(oldRule)) {
1481	    return;
1482	  }
1483	  // 新规则只接受 null：旧规则的任意非 null 样本都是反例
1484	  if (newRule.kind === 'null') {
1485	    out.push({
1486	      pointer,
1487	      value: sampleValue(oldRule),
1488	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 null`,
1489	    });
1490	    return;
1491	  }
1492	
1493	  if (newRule.kind !== 'object' && newRule.kind !== 'array') {
1494	    // 新规则是标量：旧规则为对象/数组时任何样本都被拒绝
1495	    if (oldRule.kind === 'object' || oldRule.kind === 'array') {
1496	      out.push({
1497	        pointer,
1498	        value: sampleValue(oldRule),
1499	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1500	      });
1501	      return;
1502	    }
1503	    collectScalarViolations(oldRule, newRule, pointer, out);
1504	    return;
1505	  }
1506	
1507	  if (newRule.kind === 'array') {
1508	    if (oldRule.kind !== 'array') {
1509	      out.push({
1510	        pointer,
1511	        value: sampleValue(oldRule),
1512	        message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 array`,
1513	      });
1514	      return;
1515	    }
1516	    // 元素规则收紧：用非空数组 [反例] 体现（空数组双方都会接受）
1517	    const sub: BodyViolation[] = [];
1518	    collectViolations(oldRule.items, newRule.items, `${pointer}/0`, sub);
1519	    for (const s of sub) {
1520	      out.push({ pointer: s.pointer, message: s.message, value: [s.value] });
1521	    }
1522	    return;
1523	  }
1524	
1525	  // newRule.kind === 'object'
1526	  if (oldRule.kind !== 'object') {
1527	    out.push({
1528	      pointer,
1529	      value: sampleValue(oldRule),
1530	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 object`,
1531	    });
1532	    return;
1533	  }
1534	
1535	  // (a) 新规则的必填字段必须被旧规则保证存在（旧规则未声明或仅可选即存在反例）
1536	  for (const [name, newField] of newRule.fields) {
1537	    if (!newField.required) {
1538	      continue;
1539	    }
1540	    const oldField = oldRule.fields.get(name);
1541	    if (!oldField || !oldField.required) {
1542	      out.push({
1543	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1544	        // 旧规则的最小样本不含可缺省/未声明字段，恰为反例
1545	        value: sampleValue(oldRule),
1546	        message: `新规则要求必填字段 ${JSON.stringify(name)}，旧规则允许缺省该字段`,
1547	      });
1548	    }
1549	  }
1550	
1551	  // (b) 旧规则声明的字段，在新规则下仍须被接受
1552	  for (const [name, oldField] of oldRule.fields) {
1553	    const childPointer = `${pointer}/${escapePointerSegment(name)}`;
1554	    const newField = newRule.fields.get(name);
1555	    if (!newField) {
1556	      if (!newRule.additionalProperties) {
1557	        out.push({
1558	          pointer: childPointer,
1559	          value: sampleObjectWith(oldRule, name, sampleValue(oldField.rule)),
1560	          message: `新规则拒绝旧规则允许的字段 ${JSON.stringify(name)}（新规则未声明且 additionalProperties 为 false）`,
1561	        });
1562	      }
1563	      continue;
1564	    }
1565	    const sub: BodyViolation[] = [];
1566	    collectViolations(oldField.rule, newField.rule, childPointer, sub);
1567	    for (const s of sub) {
1568	      out.push({
1569	        pointer: s.pointer,
1570	        message: s.message,
1571	        value: sampleObjectWith(oldRule, name, s.value),
1572	      });
1573	    }
1574	  }
1575	
1576	  // (c) 旧规则允许未声明的额外字段时，新规则必须同样放行这些字段
1577	  if (oldRule.additionalProperties) {
1578	    if (!newRule.additionalProperties) {
1579	      const name = freshFieldName(oldRule.fields, newRule.fields);
1580	      out.push({
1581	        pointer: `${pointer}/${escapePointerSegment(name)}`,
1582	        value: sampleObjectWith(oldRule, name, 0),
1583	        message: '旧规则允许未声明的额外字段，新规则拒绝（additionalProperties 为 false）',
1584	      });
1585	    } else {
1586	      // 新规则虽放行额外字段，但其新声明的字段会约束旧版原本自由的取值
1587	      for (const [name, newField] of newRule.fields) {
1588	        if (oldRule.fields.has(name)) {
1589	          continue;
1590	        }
1591	        out.push({
1592	          pointer: `${pointer}/${escapePointerSegment(name)}`,
1593	          value: sampleObjectWith(oldRule, name, violateValue(newField.rule)),
1594	          message: `旧规则对额外字段 ${JSON.stringify(name)} 不限制取值，新规则要求其为 ${kindLabel(newField.rule)}`,
1595	        });
1596	      }
1597	    }
1598	  }
1599	}
