1602	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
1603	  if (endpoint.bodyRule) {
1604	    return {
1605	      method: endpoint.method,
1606	      path: endpoint.path,
1607	      headers: { 'Content-Type': 'application/json' },
1608	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
1609	    };
