1614	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
1615	  const base = { method: oldEp.method, path: oldEp.path };
1616	
1617	  if (!newEp) {
1618	    return {
1619	      ...base,
1620	      compatible: false,
1621	      reasons: [
1622	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
1623	      ],
1624	      example: acceptedRequestExample(oldEp),
1625	    };
1626	  }
1627	
1628	  if (!oldEp.bodyRule && !newEp.bodyRule) {
1629	    return { ...base, compatible: true, reasons: [] };
1630	  }
1631	
1632	  if (!oldEp.bodyRule && newEp.bodyRule) {
1633	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1634	    return {
1635	      ...base,
1636	      compatible: false,
1637	      reasons: [
1638	        {
1639	          pointer: '',
1640	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1641	        },
1642	      ],
1643	      example: {
1644	        ...base,
1645	        headers: { 'Content-Type': 'application/json' },
1646	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1647	      },
1648	    };
1649	  }
1650	
1651	  if (oldEp.bodyRule && !newEp.bodyRule) {
1652	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1653	  }
1654	
1655	  const violations: BodyViolation[] = [];
1656	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1657	  if (violations.length === 0) {
1658	    return { ...base, compatible: true, reasons: [] };
1659	  }
1660	  return {
1661	    ...base,
1662	    compatible: false,
1663	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1664	    example: {
1665	      ...base,
1666	      headers: { 'Content-Type': 'application/json' },
1667	      body: JSON.stringify(violations[0].value),
1668	    },
1669	  };
1670	}
