1672	function compareConfigs(
1673	  oldSpecs: readonly EndpointSpec[],
1674	  newSpecs: readonly EndpointSpec[],
1675	  oldFile: string,
1676	  newFile: string,
1677	): CompareReport {
1678	  const newByKey = new Map<string, EndpointSpec>();
1679	  for (const spec of newSpecs) {
1680	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1681	  }
1682	  const endpoints = oldSpecs.map((spec) =>
1683	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1684	  );
1685	  return {
1686	    compatible: endpoints.every((ep) => ep.compatible),
1687	    oldFile,
1688	    newFile,
1689	    endpoints,
1690	  };
1691	}
