1693	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1694	  const oldFile = path.resolve(oldArg);
1695	  const newFile = path.resolve(newArg);
1696	
1697	  const attempt = async (
1698	    file: string,
1699	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1700	    try {
1701	      return { specs: await loadSpecsFromFile(file) };
1702	    } catch (e) {
1703	      return { error: describeError(e) };
1704	    }
1705	  };
1706	
1707	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1708	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1709	  let failed = false;
1710	  if (oldResult.error !== undefined) {
1711	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1712	    failed = true;
1713	  }
1714	  if (newResult.error !== undefined) {
1715	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1716	    failed = true;
1717	  }
1718	  if (failed) {
1719	    process.exit(2);
1720	  }
1721	
1722	  const report = compareConfigs(
1723	    oldResult.specs as EndpointSpec[],
1724	    newResult.specs as EndpointSpec[],
1725	    oldFile,
1726	    newFile,
1727	  );
1728	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1729	  process.exit(report.compatible ? 0 : 1);
1730	}
