1856	// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
1857	function unescapeRefSegment(
1858	  segment: string,
1859	  ref: string,
1860	  ctx: ImportCtx,
1861	  where: string,
1862	): string {
1863	  let out = '';
1864	  for (let i = 0; i < segment.length; i += 1) {
1865	    const ch = segment[i];
1866	    if (ch === '~') {
1867	      const next = segment[i + 1];
1868	      if (next === '0') {
1869	        out += '~';
