// JSON Pointer 段反转义：~1 -> /，~0 -> ~；其余 “~” 用法非法
function unescapeRefSegment(
  segment: string,
  ref: string,
  ctx: ImportCtx,
  where: string,
): string {
  let out = '';
  for (let i = 0; i < segment.length; i += 1) {
    const ch = segment[i];
    if (ch === '~') {
      const next = segment[i + 1];
      if (next === '0') {
        out += '~';
        i += 1;
      } else if (next === '1') {
        out += '/';
        i += 1;
      } else {
        importFail(ctx, where, `$ref "${ref}" 含非法的 "~" 转义（仅支持 ~0 与 ~1）`);
