3050	// 本机请求重放与响应差异报告（replay 子命令）
3051	// ---------------------------------------------------------------------------
3052	//
3053	// 读取 GET /__contractlab/requests 的完整 JSON 快照，按输入顺序保留原编号，
3054	// 把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口：前一条结束才发下一条，
3055	// 每次执行每条只尝试一次，不跟随重定向。仅比较实际响应的状态码与正文和记录
3056	// 中的计划响应（计划正文按 UTF-8 编码）；可选 --strategy 比较策略按
3057	// “方法 + 字面路径”为接口选择正文 JSON 语义比较（见下），未选中的接口仍按
3058	// 正文原始字节比较。不比较响应头，也不依据记录版本与发送状态判定——
3059	// pending / sent / interrupted 均可重放，400/404/500 同样按内容比较。
3060	// 不监听端口、不修改文件；已发送的请求可能已被目标处理，不重载、清空或
3061	// 回滚目标状态。
3062	//
3063	// 仅重放 GET/POST；target 须为以 "/" 开头的合法 HTTP 请求目标，原样发送
3064	// （保留查询串与百分号编码，不归一化路径）；禁止重放 /__contractlab 本身及
3065	// /__contractlab/ 前缀路径。每条记录另须有 200–599 的计划响应状态与文本正文。
3066	// 参数与全部记录（含可发送的头名称和值）有效后才连接；参数或快照失败退出 2，
3067	// stderr 给原因，stdout 为空且不发任何请求。
3068	//
3069	// 每条请求的总超时自开始连接覆盖完整收发，持续来数据也不延长；连接失败、
3070	// 超时或响应中途断开记通信失败，关闭连接后继续下一条（部分响应不算完整）。
3071	
3072	// 重放时剥离的头（小写）：原 Host / Expect / HTTP 逐跳与分帧头；
3073	// Connection 头指名的头名也一并剥离。Host 与 Content-Length 按目标和实际
3074	// 字节数重建。
3075	const REPLAY_STRIP_HEADERS: ReadonlySet<string> = new Set([
3076	  'host',
3077	  'expect',
3078	  'connection',
3079	  'keep-alive',
3080	  'content-length',
3081	  'transfer-encoding',
3082	  'te',
3083	  'trailer',
3084	  'upgrade',
3085	  'proxy-authenticate',
3086	  'proxy-authorization',
3087	]);
