3089	// 一条待重放的请求：共享快照校验之上再经重放专用校验
3090	interface ReplayRequest {
3091	  readonly id: number;
3092	  readonly method: 'GET' | 'POST';
3093	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
3094	  readonly target: string;
3095	  // target 去掉查询串后的字面路径（比较策略按“方法 + 路径”选择接口）
3096	  readonly path: string;
3097	  // 过滤后的业务头：名称大小写、重复项与在线顺序原样保留
3098	  readonly headers: readonly [string, string][];
3099	  readonly body: Buffer;
3100	  readonly plannedStatus: number;
3101	  readonly plannedBody: string;
3102	}
3103	
3104	// target 须为以 "/" 开头的合法 HTTP 请求目标：不含空白与控制字符，
3105	// 且每个字符都在 Latin-1 内（与 Node 客户端对 path 的接受范围一致）
3106	function validateReplayTarget(target: string, where: string): void {
3107	  if (target.length === 0 || !target.startsWith('/')) {
3108	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
3109	  }
3110	  for (const ch of target) {
3111	    const code = ch.charCodeAt(0);
3112	    if (code <= 0x20 || code === 0x7f) {
3113	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
3114	    }
3115	    if (code > 0xff) {
3116	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
3117	    }
3118	  }
3119	}
3120	
3121	// 过滤并校验待发送的业务头：剥离 Host/Expect/逐跳/分帧头（含 Connection
3122	// 指名的头），其余按原顺序、大小写与重复项保留；保留的头名称与值必须可发送。
3123	function filterReplayHeaders(
3124	  rawHeaders: readonly string[],
3125	  where: string,
3126	): [string, string][] {
3127	  const connectionNamed = new Set<string>();
3128	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3129	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
3130	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
3131	        const name = token.trim().toLowerCase();
3132	        if (name !== '') {
3133	          connectionNamed.add(name);
3134	        }
3135	      }
3136	    }
3137	  }
3138	  const out: [string, string][] = [];
3139	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3140	    const name = rawHeaders[j] as string;
3141	    const value = rawHeaders[j + 1] as string;
3142	    const lower = name.toLowerCase();
3143	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
3144	      continue;
3145	    }
3146	    if (!HEADER_NAME_RE.test(name)) {
3147	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
3148	    }
3149	    for (let k = 0; k < value.length; k += 1) {
3150	      const code = value.charCodeAt(k);
3151	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
3152	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
3153	        snapshotFail(
3154	          `${where}[${j + 1}]`,
3155	          `头 ${JSON.stringify(name)} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
3156	        );
3157	      }
3158	    }
3159	    out.push([name, value]);
3160	  }
3161	  return out;
3162	}
