3164	function parseReplayRecord(raw: unknown, index: number, seen: Set<number>): ReplayRequest {
3165	  const where = `records[${index}]`;
3166	  // 先完整经历与 verify 相同的快照校验（含 target/path 一致性与正文无损性）
3167	  const base = parseSnapshotRecord(raw, index, seen);
3168	
3169	  if (base.method !== 'GET' && base.method !== 'POST') {
3170	    snapshotFail(
3171	      `${where}.request.method`,
3172	      `仅支持重放 GET/POST，收到 ${JSON.stringify(base.method)}`,
3173	    );
3174	  }
3175	  validateReplayTarget(base.target, `${where}.request.target`);
3176	  if (base.path === ADMIN_BASE || base.path.startsWith(ADMIN_PREFIX)) {
3177	    snapshotFail(
3178	      `${where}.request.target`,
3179	      `指向管理入口（${ADMIN_BASE} 本身及 ${ADMIN_PREFIX} 前缀），禁止重放`,
3180	    );
3181	  }
3182	
3183	  // 每条记录另须有 200–599 的计划响应状态与文本正文（比较基准）
3184	  const prWhere = `${where}.plannedResponse`;
3185	  const planned = (raw as Record<string, unknown>).plannedResponse;
3186	  if (!isPlainObject(planned)) {
3187	    snapshotFail(prWhere, '必须是对象（重放需要计划响应状态与文本正文）');
3188	  }
3189	  const { status, body } = planned;
3190	  if (!Number.isInteger(status) || (status as number) < 200 || (status as number) > 599) {
3191	    snapshotFail(
3192	      `${prWhere}.status`,
3193	      `必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`,
3194	    );
3195	  }
3196	  if (typeof body !== 'string') {
3197	    snapshotFail(`${prWhere}.body`, '必须是文本字符串');
3198	  }
3199	  if (hasLoneSurrogate(body as string)) {
3200	    snapshotFail(
3201	      `${prWhere}.body`,
3202	      '含孤立代理项（lone surrogate）：按 UTF-8 编码会被替换字符改写，无法作为无损的比较基准',
3203	    );
3204	  }
3205	
3206	  return {
3207	    id: base.id,
3208	    method: base.method,
3209	    target: base.target,
3210	    path: base.path,
3211	    headers: filterReplayHeaders(base.rawHeaders, `${where}.request.rawHeaders`),
3212	    body: base.body,
3213	    plannedStatus: status as number,
3214	    plannedBody: body as string,
3215	  };
3216	}
