3246	// ---------------------------------------------------------------------------
3247	// 响应正文 JSON 语义比较（replay --strategy，可选）
3248	// ---------------------------------------------------------------------------
3249	//
3250	// 比较策略文件按“方法（GET/POST）+ 去掉查询串后的字面路径”为接口选择 JSON
3251	// 语义比较；未选中的接口仍按正文原始字节比较。每个接口可附 RFC 6901 忽略
3252	// 指针数组：指针处的值、存在性与子树不参与比较（不删除数组项、不移动下标；
3253	// 两侧都无目标时无影响；祖先类型不同仍照常报告）。重复或父子重叠的
3254	// 忽略项不改变结果。
3255	//
3256	// 策略、整份快照与所选记录的计划正文全部校验通过后才连接：所选计划正文须为
3257	// UTF-8 JSON（仅可剥离单个开头 BOM，空正文非法），忽略规则不豁免解析；
3258	// 失败退出 2、stderr 定位文件与字段、stdout 为空且不发任何请求。
3259	//
3260	// JSON 语义（不依赖媒体类型）：对象只看自有字段，忽略键顺序与排版；数组按
3261	// 原下标比较（顺序有意义，多出或缺失的元素在其下标报告，不另报长度）；
3262	// 标量不转换类型，数字按解析数值比较（0 与 -0 等价），缺失与 null 不同。
3263	// 状态码始终精确比较，不比较响应头。
3264	
3265	// 一个接口的 JSON 语义比较策略
3266	interface JsonCompareEndpoint {
3267	  // 规范化后的忽略指针集合（RFC 6901，根为 ""）；重复与父子重叠不影响结果
3268	  readonly ignore: ReadonlySet<string>;
3269	}
3270	
3271	// 比较策略：键为 "METHOD /literal/path"（路径不含查询串）
3272	type JsonCompareStrategy = ReadonlyMap<string, JsonCompareEndpoint>;
3273	
3274	// 由解析出的指针段构造规范化指针文本（根为 ""），用于忽略集合的去重与查找
3275	function canonicalPointer(segments: readonly string[]): string {
3276	  return segments.length === 0 ? '' : `/${segments.map(escapePointerSegment).join('/')}`;
3277	}
3278	
3279	function parseStrategyEndpoint(
3280	  raw: unknown,
3281	  index: number,
3282	  seen: Set<string>,
3283	  endpoints: Map<string, JsonCompareEndpoint>,
3284	): void {
3285	  const where = `endpoints[${index}]`;
3286	  if (!isPlainObject(raw)) {
3287	    throw new ConfigError(`${where} 必须是对象`);
3288	  }
3289	  for (const key of Object.keys(raw)) {
3290	    if (key !== 'method' && key !== 'path' && key !== 'ignore') {
3291	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
3292	    }
3293	  }
3294	  const { method, path: routePath, ignore } = raw;
3295	  if (method !== 'GET' && method !== 'POST') {
3296	    throw new ConfigError(
3297	      `${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`,
3298	    );
3299	  }
3300	  if (typeof routePath !== 'string') {
3301	    throw new ConfigError(`${where}.path 必须是字符串`);
3302	  }
3303	  validatePath(routePath, where);
3304	
3305	  const ignoreSet = new Set<string>();
3306	  if (ignore !== undefined) {
3307	    if (!Array.isArray(ignore)) {
3308	      throw new ConfigError(`${where}.ignore 必须是 RFC 6901 指针字符串数组`);
3309	    }
3310	    ignore.forEach((rawPointer, j) => {
3311	      // 支持根（""）、空字段名（"/"）、__proto__ 与 ~0/~1 转义；
3312	      // 重复或父子重叠的忽略项不改变结果（集合语义）
3313	      const segments = parseJsonPointer(rawPointer, `${where}.ignore[${j}]`, '忽略指针');
3314	      ignoreSet.add(canonicalPointer(segments));
3315	    });
3316	  }
3317	
3318	  const key = `${method as string} ${routePath}`;
3319	  if (seen.has(key)) {
3320	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
3321	  }
3322	  seen.add(key);
3323	  endpoints.set(key, { ignore: ignoreSet });
3324	}
3325	
3326	function parseCompareStrategy(raw: unknown): JsonCompareStrategy {
3327	  if (!isPlainObject(raw)) {
3328	    throw new ConfigError('比较策略顶层必须是 JSON 对象（含 endpoints）');
3329	  }
3330	  for (const key of Object.keys(raw)) {
3331	    if (key !== 'endpoints') {
3332	      throw new ConfigError(`比较策略顶层含未知字段 "${key}"`);
3333	    }
3334	  }
3335	  const { endpoints } = raw;
3336	  if (!Array.isArray(endpoints)) {
3337	    throw new ConfigError('endpoints 必须是数组');
3338	  }
3339	  const map = new Map<string, JsonCompareEndpoint>();
3340	  const seen = new Set<string>();
3341	  endpoints.forEach((ep, i) => parseStrategyEndpoint(ep, i, seen, map));
3342	  return map;
3343	}
