3368	// 解析 JSON 语义比较的一侧正文文本：仅可剥离单个开头 BOM；空正文非法。
3369	// 忽略规则不豁免解析——两侧都必须先通过本解析。
3370	function parseSemanticJson(text: string): { readonly ok: true; readonly value: unknown } | { readonly ok: false; readonly reason: string } {
3371	  const stripped = text.startsWith('\uFEFF') ? text.slice(1) : text;
3372	  if (stripped === '') {
3373	    return { ok: false, reason: '是空正文，不是合法 JSON' };
3374	  }
3375	  try {
3376	    return { ok: true, value: JSON.parse(stripped) };
3377	  } catch (e) {
3378	    return { ok: false, reason: `不是合法 JSON：${describeError(e)}` };
3379	  }
3380	}
3381	
3382	// 严格 UTF-8 解码（保留开头 BOM 字符，交由 parseSemanticJson 统一处理）
3383	function decodeUtf8Strict(body: Buffer): { readonly ok: true; readonly text: string } | { readonly ok: false; readonly reason: string } {
3384	  try {
3385	    return { ok: true, text: new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body) };
3386	  } catch {
3387	    return { ok: false, reason: '不是合法 UTF-8' };
3388	  }
3389	}
3390	
3391	// 正文差异中“该侧不存在此节点”的标记（缺失与 null 不同）
3392	const MISSING_NODE = 'missing';
3393	
3394	interface BodyDifference {
3395	  // RFC 6901 位置（根为 ""）
3396	  readonly pointer: string;
3397	  // 计划值 / 实际值（JSON 原值）；该侧不存在时为 "missing"
3398	  readonly planned: unknown;
3399	  readonly actual: unknown;
3400	}
3401	
3402	// 递归列出全部未忽略的独立正文差异：节点缺失或类型不同只报该节点，不再深入
3403	function diffJsonValues(
3404	  planned: unknown,
3405	  actual: unknown,
3406	  ignore: ReadonlySet<string>,
3407	  path: readonly string[],
3408	  out: BodyDifference[],
3409	): void {
3410	  if (ignore.has(canonicalPointer(path))) {
3411	    return; // 忽略指针处的值、存在性与子树
3412	  }
3413	  const plannedType = jsonTypeOf(planned);
3414	  const actualType = jsonTypeOf(actual);
3415	  if (plannedType !== actualType) {
3416	    out.push({ pointer: canonicalPointer(path), planned, actual });
3417	    return;
3418	  }
3419	  if (plannedType === 'object') {
3420	    // 只看自有字段，忽略键顺序（含空字段名与 __proto__）
3421	    const p = planned as Record<string, unknown>;
3422	    const a = actual as Record<string, unknown>;
3423	    for (const key of Object.keys(p)) {
3424	      const childPath = [...path, key];
3425	      if (Object.prototype.hasOwnProperty.call(a, key)) {
3426	        diffJsonValues(p[key], a[key], ignore, childPath, out);
3427	      } else if (!ignore.has(canonicalPointer(childPath))) {
3428	        out.push({ pointer: canonicalPointer(childPath), planned: p[key], actual: MISSING_NODE });
3429	      }
3430	    }
3431	    for (const key of Object.keys(a)) {
3432	      if (!Object.prototype.hasOwnProperty.call(p, key)) {
3433	        const childPath = [...path, key];
3434	        if (!ignore.has(canonicalPointer(childPath))) {
3435	          out.push({ pointer: canonicalPointer(childPath), planned: MISSING_NODE, actual: a[key] });
3436	        }
3437	      }
3438	    }
3439	    return;
3440	  }
3441	  if (plannedType === 'array') {
3442	    // 按原下标比较：顺序有意义；多出或缺失的元素在其下标报告，不另报长度；
3443	    // 被忽略的下标不参与比较，但不删除数组项、不移动其余下标
3444	    const p = planned as unknown[];
3445	    const a = actual as unknown[];
3446	    const n = Math.max(p.length, a.length);
3447	    for (let i = 0; i < n; i += 1) {
3448	      const childPath = [...path, String(i)];
3449	      if (ignore.has(canonicalPointer(childPath))) {
3450	        continue;
3451	      }
3452	      if (i >= p.length) {
3453	        out.push({ pointer: canonicalPointer(childPath), planned: MISSING_NODE, actual: a[i] });
3454	      } else if (i >= a.length) {
3455	        out.push({ pointer: canonicalPointer(childPath), planned: p[i], actual: MISSING_NODE });
3456	      } else {
3457	        diffJsonValues(p[i], a[i], ignore, childPath, out);
3458	      }
3459	    }
3460	    return;
3461	  }
3462	  // 标量不转换类型；数字按解析数值比较（0 与 -0 等价）
3463	  if (planned !== actual) {
3464	    out.push({ pointer: canonicalPointer(path), planned, actual });
3465	  }
3466	}
3467	
3468	interface ReplayResponse {
3469	  readonly status: number;
3470	  readonly body: Buffer;
3471	}
3472	
3473	type ReplayExchange =
3474	  | { readonly ok: true; readonly response: ReplayResponse }
3475	  | { readonly ok: false; readonly reason: string };
3476	
3477	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
3478	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
3479	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
3480	  return new Promise((resolve) => {
3481	    let settled = false;
3482	    const done = (outcome: ReplayExchange): void => {
3483	      if (!settled) {
3484	        settled = true;
3485	        clearTimeout(timer);
3486	        resolve(outcome);
3487	      }
3488	    };
3489	
3490	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
3491	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
3492	    const headers: string[] = [];
3493	    for (const [name, value] of request.headers) {
3494	      headers.push(name, value);
3495	    }
3496	    headers.push('Host', `127.0.0.1:${port}`);
3497	    headers.push('Content-Length', String(request.body.byteLength));
3498	    headers.push('Connection', 'close');
3499	
3500	    const req = http.request({
3501	      host: '127.0.0.1',
3502	      port,
3503	      method: request.method,
3504	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
3505	      headers,
3506	      agent: false, // 不连接池化：一次一条，每条只尝试一次
3507	    });
3508	
3509	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
3510	    const timer = setTimeout(() => {
3511	      req.destroy();
3512	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
3513	    }, timeoutMs);
3514	
3515	    req.on('response', (res) => {
3516	      const chunks: Buffer[] = [];
3517	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
3518	      res.on('end', () => {
3519	        done({
3520	          ok: true,
3521	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
3522	        });
3523	      });
3524	      res.on('aborted', () => {
3525	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3526	      });
3527	      res.on('error', (e: unknown) => {
3528	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
3529	      });
3530	      res.on('close', () => {
3531	        if (!res.complete) {
3532	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3533	        }
3534	      });
3535	    });
3536	    req.on('error', (e: Error) => {
3537	      done({ ok: false, reason: `通信失败：${e.message}` });
3538	    });
3539	    req.end(request.body);
3540	  });
3541	}
3542	
3543	// 完整响应的无损 JSON 表示（与请求记录正文同一套编码规则）
3544	function replayResponseJson(response: ReplayResponse): {
3545	  status: number;
3546	  body: { encoding: 'utf-8' | 'base64'; content: string };
3547	} {
3548	  return { status: response.status, body: encodeBodyLosslessly(response.body) };
3549	}
3550	
3551	type ReplayResultEntry =
3552	  | {
3553	      readonly id: number;
3554	      readonly outcome: 'same';
3555	      readonly response: ReturnType<typeof replayResponseJson>;
3556	    }
3557	  | {
3558	      readonly id: number;
3559	      readonly outcome: 'different';
3560	      // 差异点：状态码不同 / 正文不同（可同时为真；JSON 模式下正文按语义比较）
3561	      readonly differences: { readonly status: boolean; readonly body: boolean };
3562	      // 仅 JSON 语义比较模式：两侧均可解析时列出全部未忽略的独立正文差异
3563	      readonly bodyDifferences?: readonly BodyDifference[];
3564	      // 仅 JSON 语义比较模式：实际响应正文非 UTF-8 或非 JSON 时的原因
3565	      readonly bodyError?: string;
3566	      readonly planned: ReturnType<typeof replayResponseJson>;
3567	      readonly response: ReturnType<typeof replayResponseJson>;
3568	    }
3569	  | { readonly id: number; readonly outcome: 'failed'; readonly reason: string };
3570	
3571	interface ReplayReport {
3572	  readonly requestsFile: string;
3573	  readonly port: number;
3574	  readonly timeoutMs: number;
3575	  readonly total: number;
3576	  readonly same: number;
3577	  readonly different: number;
3578	  readonly failed: number;
3579	  readonly results: readonly ReplayResultEntry[];
3580	}
3581	
3582	async function runReplay(
3583	  requestsArg: string,
3584	  port: number,
3585	  timeoutMs: number,
3586	  strategyArg?: string,
3587	): Promise<never> {
3588	  const requestsFile = path.resolve(requestsArg);
3589	
3590	  // 比较策略（可选）：先读取并严格校验；失败退出 2，不发任何请求
3591	  let strategy: JsonCompareStrategy | undefined;
3592	  if (strategyArg !== undefined) {
3593	    const strategyFile = path.resolve(strategyArg);
3594	    try {
3595	      strategy = await loadStrategyFromFile(strategyFile);
3596	    } catch (e) {
3597	      process.stderr.write(`${APP_NAME}: replay 比较策略：${describeError(e)}\n`);
3598	      process.exit(2);
3599	    }
3600	  }
3601	
3602	  // 参数与全部记录有效后才连接：任何快照错误都不发任何请求
3603	  let requests: ReplayRequest[];
3604	  try {
3605	    requests = await loadReplaySnapshotFromFile(requestsFile);
3606	  } catch (e) {
3607	    process.stderr.write(`${APP_NAME}: replay 请求快照：${describeError(e)}\n`);
3608	    process.exit(2);
3609	  }
3610	
3611	  // 策略选中的记录：计划正文须为 UTF-8 JSON（仅可剥离单个开头 BOM，空正文
3612	  // 非法），忽略规则不豁免解析；与策略、快照一起全部校验通过后才连接
3613	  const jsonPlans: ({ readonly ignore: ReadonlySet<string>; readonly planned: unknown } | null)[] =
3614	    requests.map((request, i) => {
3615	      const endpoint = strategy?.get(`${request.method} ${request.path}`);
3616	      if (endpoint === undefined) {
3617	        return null;
3618	      }
3619	      const parsed = parseSemanticJson(request.plannedBody);
3620	      if (!parsed.ok) {
3621	        process.stderr.write(
3622	          `${APP_NAME}: replay 请求快照：请求记录快照文件 ${requestsFile} 校验失败：` +
3623	            `records[${i}].plannedResponse.body ${parsed.reason}` +
3624	            `（策略为 ${request.method} ${request.path} 选择 JSON 语义比较）\n`,
3625	        );
3626	        process.exit(2);
3627	      }
3628	      return { ignore: endpoint.ignore, planned: parsed.value };
3629	    });
3630	
3631	  // 按输入顺序保留原编号逐条重放：前一条结束才发下一条
3632	  const results: ReplayResultEntry[] = [];
3633	  for (const [index, request] of requests.entries()) {
3634	    const exchange = await replayOne(port, request, timeoutMs);
3635	    if (!exchange.ok) {
3636	      results.push({ id: request.id, outcome: 'failed', reason: exchange.reason });
3637	      continue;
3638	    }
3639	    const { response } = exchange;
3640	    // 状态码始终精确比较；不比较响应头
3641	    const statusDiff = response.status !== request.plannedStatus;
3642	    const plan = jsonPlans[index];
3643	    if (plan == null) {
3644	      // 字节比较：仅比较状态码与正文原始字节；计划正文按 UTF-8 编码
3645	      const bodyDiff = !response.body.equals(Buffer.from(request.plannedBody, 'utf8'));
3646	      if (!statusDiff && !bodyDiff) {
3647	        results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
3648	      } else {
3649	        results.push({
3650	          id: request.id,
3651	          outcome: 'different',
3652	          differences: { status: statusDiff, body: bodyDiff },
3653	          planned: {
3654	            status: request.plannedStatus,
3655	            body: { encoding: 'utf-8', content: request.plannedBody },
3656	          },
3657	          response: replayResponseJson(response),
3658	        });
3659	      }
3660	      continue;
3661	    }
3662	
3663	    // JSON 语义比较：不依赖媒体类型；实际完整响应非 UTF-8 或非 JSON 记正文
3664	    // 差异（说明原因）并继续后续记录
3665	    let bodyDiff: boolean;
3666	    let bodyDifferences: BodyDifference[] | undefined;
3667	    let bodyError: string | undefined;
3668	    const decoded = decodeUtf8Strict(response.body);
3669	    const actual = decoded.ok ? parseSemanticJson(decoded.text) : decoded;
3670	    if (!actual.ok) {
3671	      bodyDiff = true;
3672	      bodyError = `实际响应正文${actual.reason}，无法进行 JSON 语义比较`;
3673	    } else {
3674	      const diffs: BodyDifference[] = [];
3675	      diffJsonValues(plan.planned, actual.value, plan.ignore, [], diffs);
3676	      bodyDiff = diffs.length > 0;
3677	      if (bodyDiff) {
3678	        bodyDifferences = diffs;
3679	      }
3680	    }
3681	    if (!statusDiff && !bodyDiff) {
3682	      results.push({ id: request.id, outcome: 'same', response: replayResponseJson(response) });
3683	    } else {
3684	      results.push({
3685	        id: request.id,
3686	        outcome: 'different',
3687	        differences: { status: statusDiff, body: bodyDiff },
3688	        // 差异项保留计划与实际正文的无损表示
3689	        ...(bodyDifferences === undefined ? {} : { bodyDifferences }),
3690	        ...(bodyError === undefined ? {} : { bodyError }),
3691	        planned: {
3692	          status: request.plannedStatus,
3693	          body: { encoding: 'utf-8', content: request.plannedBody },
3694	        },
3695	        response: replayResponseJson(response),
3696	      });
3697	    }
3698	  }
3699	
3700	  const same = results.filter((r) => r.outcome === 'same').length;
3701	  const different = results.filter((r) => r.outcome === 'different').length;
3702	  const failed = results.filter((r) => r.outcome === 'failed').length;
3703	  const report: ReplayReport = {
3704	    requestsFile,
3705	    port,
3706	    timeoutMs,
3707	    total: results.length,
3708	    same,
3709	    different,
3710	    failed,
3711	    results,
3712	  };
3713	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
3714	  // 空快照或全部相同退出 0；存在差异或通信失败退出 1
3715	  process.exit(different === 0 && failed === 0 ? 0 : 1);
3716	}
3717	
3718	// ---------------------------------------------------------------------------
3719	// 离线响应分支可达性诊断（reach 子命令）
3720	// ---------------------------------------------------------------------------
3721	//
3722	// 读取一份通过与 serve 完全相同严格校验的场景配置与一个 POST 接口的字面路径，
3723	// 离线诊断该接口 branches 中每一分支及兜底 responses 是否可达：
3724	//   reachable      —— 存在通过正文检查的请求正文，且该正文首先命中此支；
3725	//   covered        —— 存在满足此支条件的合格正文，但它们全部首先命中前序分支
3726	//                      （遮挡按前序分支的命中并集判定，不是单支包含，也不抽样）；
3727	//   contradictory  —— 条件与正文规则矛盾，不存在满足条件的合格正文。
3728	// 不监听、不发送请求、不修改任何文件。可达分支/兜底各给一份完整请求样例
3729	// （方法、路径、必要头、原始 JSON 正文，补全全部必填字段），样例须通过正文
3730	// 检查并实际选中所报分支或兜底。
3731	//
3732	// 诊断范围（超出即整份拒绝，退出 2）：
3733	// - 接口必须是 POST、声明了非空 branches；
3734	// - 根 requestBody 必须是 object（可附 nullable）；
3735	// - 每个 when 指针必须是**单段** RFC 6901 指针，指向根对象**已声明的标量字段**
3736	//   （根指针 ""、多段指针、未声明字段、object/array 字段均拒绝）；其余字段仍
3737	//   完全按现有递归规则参与“合格正文”的构造与判定。空字段名、__proto__、
3738	//   ~0/~1 转义按原语义处理。
3739	//
3740	// 判定精确依据现有 type/enum/nullable/必填可选/额外字段语义：缺失与 null 分开、
3741	// 0 与 -0 等价、不转换类型；根可空时 JSON null 也参与兜底可达性判断。
3742	
3743	class ReachError extends Error {
3744	  constructor(message: string) {
3745	    super(message);
3746	    this.name = 'ReachError';
3747	  }
3748	}
