test('输入失败：非法策略与所选记录计划正文非 JSON，退出 2、stderr 定位、stdout 为空且零请求', {
  timeout: 60_000,
}, async (t) => {
  const dir = await makeTempDir(t);

  // 计数型目标：任何输入失败都不得有请求到达
  let hits = 0;
  const counter = http.createServer((req, res) => {
    hits += 1;
    req.resume();
    req.on('end', () => res.end('{"ok":true}'));
  });
  await new Promise<void>((resolve) => counter.listen(0, '127.0.0.1', resolve));
  t.after(() => counter.close());
  const address = counter.address();
  const port = typeof address === 'object' && address ? address.port : 0;

  const okSnapshot = await writeText(
    dir,
    'ok.json',
    makeSnapshot([makeRecord(1, { target: '/api/json', plannedBody: '{"a":1}' })]),
  );
  const okStrategy = await writeText(
    dir,
    'ok-strategy.json',
    makeStrategy([{ method: 'GET', path: '/api/json' }]),
  );

  // 策略文件本身的失败：stderr 指明策略文件
  const strategyCases: { name: string; strategy: string; expect: RegExp }[] = [
    { name: '策略不是合法 JSON', strategy: '{bad', expect: /比较策略文件.*不是合法 JSON/ },
    { name: '顶层未知字段', strategy: '{"endpoints":[],"extra":1}', expect: /未知字段 "extra"/ },
    {
      name: '接口未知字段',
      strategy: makeStrategy([{ method: 'GET', path: '/api/json', mode: 'json' }]),
      expect: /endpoints\[0\].*未知字段 "mode"/,
    },
    {
      name: '重复接口',
      strategy: makeStrategy([
        { method: 'GET', path: '/api/json' },
        { method: 'GET', path: '/api/json' },
      ]),
      expect: /endpoints\[1\].*重复/,
    },
    {
      name: '非法方法',
      strategy: makeStrategy([{ method: 'PUT', path: '/api/json' }]),
      expect: /endpoints\[0\]\.method/,
    },
    {
      name: '路径不以 / 开头',
      strategy: makeStrategy([{ method: 'GET', path: 'api/json' }]),
      expect: /endpoints\[0\]\.path/,
    },
    {
      name: 'ignore 非数组',
      strategy: makeStrategy([{ method: 'GET', path: '/api/json', ignore: '/a' }]),
      expect: /endpoints\[0\]\.ignore 必须是/,
    },
    {
      name: '指针非法转义',
      strategy: makeStrategy([{ method: 'GET', path: '/api/json', ignore: ['/a~2'] }]),
      expect: /endpoints\[0\]\.ignore\[0\].*非法转义/,
    },
    {
      name: '指针不以 / 开头',
      strategy: makeStrategy([{ method: 'GET', path: '/api/json', ignore: ['a'] }]),
      expect: /endpoints\[0\]\.ignore\[0\].*"\/" 开头/,
    },
    {
      name: '指针非字符串',
      strategy: makeStrategy([{ method: 'GET', path: '/api/json', ignore: [1] }]),
      expect: /endpoints\[0\]\.ignore\[0\].*指针字符串/,
    },
  ];
  for (const c of strategyCases) {
    const file = await writeText(dir, `bad-strategy-${strategyCases.indexOf(c)}.json`, c.strategy);
    const result = await runReplay(okSnapshot, port, 5_000, file);
    assert.equal(result.code, 2, `用例「${c.name}」应退出 2`);
    assert.equal(result.stdout, '', `用例「${c.name}」stdout 必须为空`);
    assert.ok(result.stderr.includes(file), `用例「${c.name}」stderr 应指明策略文件：${result.stderr}`);
    assert.match(result.stderr, c.expect, `用例「${c.name}」stderr 应定位字段`);
  }
  const missing = await runReplay(okSnapshot, port, 5_000, `${dir}/no-such-strategy.json`);
  assert.equal(missing.code, 2);
  assert.equal(missing.stdout, '');
  assert.match(missing.stderr, /no-such-strategy\.json/);

  // 所选记录的计划正文须为 UTF-8 JSON（仅可剥离单个开头 BOM，空正文非法）
  const bodyCases: { name: string; plannedBody: string; expect: RegExp }[] = [
    { name: '计划正文非 JSON', plannedBody: 'not-json', expect: /不是合法 JSON/ },
    { name: '计划正文为空', plannedBody: '', expect: /空正文/ },
    { name: '计划正文仅 BOM', plannedBody: '\uFEFF', expect: /空正文/ },
    { name: '计划正文双 BOM', plannedBody: '\uFEFF\uFEFF{"a":1}', expect: /不是合法 JSON/ },
  ];
  for (const c of bodyCases) {
    const file = await writeText(
      dir,
      `bad-body-${bodyCases.indexOf(c)}.json`,
      makeSnapshot([makeRecord(1, { target: '/api/json', plannedBody: c.plannedBody })]),
    );
    const result = await runReplay(file, port, 5_000, okStrategy);
    assert.equal(result.code, 2, `用例「${c.name}」应退出 2`);
    assert.equal(result.stdout, '', `用例「${c.name}」stdout 必须为空`);
    assert.ok(result.stderr.includes(file), `用例「${c.name}」stderr 应指明快照文件：${result.stderr}`);
    assert.match(result.stderr, /records\[0\]\.plannedResponse\.body/, `用例「${c.name}」应定位字段`);
    assert.match(result.stderr, c.expect, `用例「${c.name}」stderr 应说明原因`);
  }

  // 未被策略选中的记录：计划正文不是 JSON 也不影响（仍按字节比较）
  const unselected = await writeText(
    dir,
    'unselected.json',
    makeSnapshot([makeRecord(1, { target: '/api/other', plannedBody: 'not-json' })]),
  );
  const unselectedResult = await runReplay(unselected, port, 5_000, okStrategy);
  assert.notEqual(unselectedResult.code, 2, '未选中接口的计划正文不做 JSON 校验');

  assert.equal(hits, 1, '输入失败时不得发出任何请求（仅未选中接口用例发出 1 条）');
});

test('空快照 + 策略：退出 0，不发任何请求', { timeout: 30_000 }, async (t) => {
  const dir = await makeTempDir(t);
  const emptyFile = await writeText(
    dir,
    'empty.json',
    JSON.stringify({ note: '空快照', count: 0, records: [] }),
  );
  const strategyFile = await writeText(
    dir,
    'strategy.json',
    makeStrategy([{ method: 'GET', path: '/api/json' }]),
  );
  let hits = 0;
  const counter = http.createServer((req, res) => {
    hits += 1;
    req.resume();
    req.on('end', () => res.end('{}'));
  });
  await new Promise<void>((resolve) => counter.listen(0, '127.0.0.1', resolve));
  t.after(() => counter.close());
  const address = counter.address();
  const port = typeof address === 'object' && address ? address.port : 0;

  const result = await runReplay(emptyFile, port, 1_000, strategyFile);
  assert.equal(result.code, 0, `空快照应退出 0：${result.stderr}`);
  const report = JSON.parse(result.stdout) as JsonReplayReport;
  assert.equal(report.total, 0);
  assert.equal(hits, 0);
});

content.content:
1	// 测试共享工具：子进程运行 compare、启动真实服务、发送真实 HTTP 请求、临时目录，
2	// 以及一套**独立**的“规则是否接受某 JSON 值”参考实现与有限代表值域生成器。
3	//
4	// 重要：accepts() / domainFor() 仅依据 README.md 记录的规则语义编写，
5	// 不 import、不复制 app.ts 中的校验、比较或反例构造函数，
6	// 用以为 compare 报告提供独立的期望值来源。
7	
8	import { spawn } from 'node:child_process';
9	import { once } from 'node:events';
10	import { mkdtemp, rm, writeFile } from 'node:fs/promises';
11	import http from 'node:http';
12	import { tmpdir } from 'node:os';
13	import path from 'node:path';
14	import { fileURLToPath } from 'node:url';
15	import type { TestContext } from 'node:test';
16	
17	export const APP_PATH = fileURLToPath(new URL('../app.ts', import.meta.url));
18	
19	// ---------------------------------------------------------------------------
20	// 子进程：运行 CLI（compare 等），带有限超时——卡住必须在有限时间内失败
21	// ---------------------------------------------------------------------------
22	
23	export interface CliResult {
24	  readonly code: number;
25	  readonly stdout: string;
26	  readonly stderr: string;
27	}
28	
29	export async function runCli(args: readonly string[], timeoutMs = 20_000): Promise<CliResult> {
30	  const child = spawn(process.execPath, [APP_PATH, ...args], {
31	    stdio: ['ignore', 'pipe', 'pipe'],
32	  });
33	  let stdout = '';
34	  let stderr = '';
35	  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
36	  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));
37	
38	  let timedOut = false;
39	  const timer = setTimeout(() => {
40	    timedOut = true;
41	    child.kill('SIGKILL');
42	  }, timeoutMs);
43	  const [code, signal] = (await once(child, 'exit')) as [number | null, string | null];
44	  clearTimeout(timer);
45	
46	  if (timedOut) {
47	    throw new Error(
48	      `命令超过 ${timeoutMs}ms 未结束（疑似卡住），已强制终止：node app.ts ${args.join(' ')}`,
49	    );
50	  }
51	  if (code === null) {
52	    throw new Error(
53	      `子进程异常终止（信号 ${signal}）：node app.ts ${args.join(' ')}\nstderr:\n${stderr}`,
54	    );
55	  }
56	  return { code, stdout, stderr };
57	}
58	
59	export function runCompare(oldFile: string, newFile: string, timeoutMs = 20_000): Promise<CliResult> {
60	  return runCli(['compare', '--old', oldFile, '--new', newFile], timeoutMs);
61	}
62	
63	// ---------------------------------------------------------------------------
64	// 真实本机服务：端口 0 由操作系统分配，解析启动日志得到实际监听地址，
65	// 不依赖固定端口，也不依赖固定等待时间（事件驱动，超时兜底）。
66	// ---------------------------------------------------------------------------
67	
68	export interface RunningServer {
69	  readonly port: number;
70	  readonly stderr: () => string;
71	  readonly close: () => Promise<void>;
72	}
73	
74	export async function startServer(configPath: string, timeoutMs = 20_000): Promise<RunningServer> {
75	  const child = spawn(process.execPath, [APP_PATH, 'serve', '--config', configPath, '--port', '0'], {
76	    stdio: ['ignore', 'pipe', 'pipe'],
77	  });
78	  let stdout = '';
79	  let stderr = '';
80	  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
81	  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));
82	
83	  const port = await new Promise<number>((resolve, reject) => {
84	    let settled = false;
85	    const fail = (e: Error): void => {
86	      if (!settled) {
87	        settled = true;
88	        clearTimeout(timer);
89	        child.kill('SIGKILL');
90	        reject(e);
91	      }
92	    };
93	    const timer = setTimeout(() => {
94	      fail(
95	        new Error(
96	          `服务 ${timeoutMs}ms 内未输出监听地址（疑似卡住）\nstdout:\n${stdout}\nstderr:\n${stderr}`,
97	        ),
98	      );
99	    }, timeoutMs);
100	    child.stdout.on('data', () => {
101	      const m = stdout.match(/listening on http:\/\/127\.0\.0\.1:(\d+)/);
102	      if (m && !settled) {
103	        settled = true;
104	        clearTimeout(timer);
105	        resolve(Number(m[1]));
106	      }
107	    });
108	    child.on('exit', (code) => {
109	      fail(new Error(`服务在监听前退出（code=${code}）\nstdout:\n${stdout}\nstderr:\n${stderr}`));
110	    });
111	  });
112	
113	  const close = async (): Promise<void> => {
114	    if (child.exitCode !== null || child.signalCode !== null) {
115	      return;
116	    }
117	    child.kill('SIGTERM');
118	    const force = setTimeout(() => child.kill('SIGKILL'), 5_000);
119	    await once(child, 'exit').catch(() => undefined);
120	    clearTimeout(force);
121	  };
122	
123	  return { port, stderr: () => stderr, close };
124	}
125	
126	// ---------------------------------------------------------------------------
127	// 真实 HTTP 请求：把报告给出的完整请求（方法/路径/头/正文）原样发出
128	// ---------------------------------------------------------------------------
129	
130	export interface RawRequest {
131	  readonly method: string;
132	  readonly path: string;
133	  readonly headers: { readonly [name: string]: string };
134	  readonly body: string;
135	}
136	
137	export interface RawResponse {
138	  readonly status: number;
139	  readonly body: string;
140	}
141	
142	export function sendRequest(port: number, req: RawRequest, timeoutMs = 10_000): Promise<RawResponse> {
143	  return new Promise((resolve, reject) => {
144	    const r = http.request(
145	      { host: '127.0.0.1', port, method: req.method, path: req.path, headers: req.headers },
146	      (res) => {
147	        let body = '';
148	        res.setEncoding('utf8').on('data', (d: string) => (body += d));
149	        res.on('end', () => resolve({ status: res.statusCode ?? 0, body }));
150	      },
151	    );
152	    r.on('error', reject);
153	    r.setTimeout(timeoutMs, () => {
154	      r.destroy(new Error(`请求 ${timeoutMs}ms 内未完成（疑似卡住）：${req.method} ${req.path}`));
155	    });
156	    if (req.body !== '') {
157	      r.write(req.body);
158	    }
159	    r.end();
160	  });
161	}
162	
163	// ---------------------------------------------------------------------------
164	// 独立临时目录与配置文件：每个用例互不影响，无论成败均清理
165	// ---------------------------------------------------------------------------
166	
167	export async function makeTempDir(t: TestContext): Promise<string> {
168	  const dir = await mkdtemp(path.join(tmpdir(), 'contractlab-test-'));
169	  t.after(() => rm(dir, { recursive: true, force: true }));
170	  return dir;
171	}
172	
173	export async function writeConfig(dir: string, name: string, value: unknown): Promise<string> {
174	  const p = path.join(dir, name);
175	  await writeFile(p, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
176	  return p;
177	}
178	
179	export async function writeText(
180	  dir: string,
181	  name: string,
182	  text: string,
183	): Promise<string> {
184	  const p = path.join(dir, name);
185	  await writeFile(p, text, 'utf8');
186	  return p;
187	}
188	
189	// 场景中统一使用的可辨认成功响应：状态码与正文都足够独特，
190	// 不会与 400 校验拒绝或 404 接口缺失混淆。
191	export const SCENE_STATUS = 299;
192	export const SCENE_BODY = 'contractlab-scene-success';
193	
194	export function sceneResponse(): { status: number; headers: Record<string, never>; body: string; delay: number } {
195	  return { status: SCENE_STATUS, headers: {}, body: SCENE_BODY, delay: 0 };
196	}
197	
198	// ---------------------------------------------------------------------------
