202	export interface RuleJson {
203	  readonly type: string;
204	  readonly nullable?: boolean;
205	  readonly enum?: readonly unknown[];
206	  readonly fields?: { readonly [name: string]: RuleJson & { readonly required?: boolean } };
207	  readonly additionalProperties?: boolean;
208	  readonly items?: RuleJson;
209	  readonly required?: boolean;
210	}
211	
212	function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
213	  return typeof value === 'object' && value !== null && !Array.isArray(value);
214	}
215	
216	// 标量类型的取值是否通过枚举候选（数字按数值相等，0 与 -0 等价，不做类型转换）
217	function enumAccepts(rule: RuleJson, value: unknown): boolean {
218	  return rule.enum === undefined || rule.enum.some((candidate) => candidate === value);
219	}
220	
221	export function accepts(rule: RuleJson, value: unknown): boolean {
222	  // nullable:true 在原接受集合上加入 null；null 被接受时不产生子节点差异；
223	  // 有枚举时可空不越过枚举：null 仍须列入候选才被接受
224	  if (value === null && rule.nullable === true) {
225	    return enumAccepts(rule, null);
226	  }
227	  switch (rule.type) {
228	    case 'string':
229	      return typeof value === 'string' && enumAccepts(rule, value);
230	    case 'boolean':
231	      return typeof value === 'boolean' && enumAccepts(rule, value);
232	    case 'null':
233	      return value === null;
234	    case 'number':
235	      return typeof value === 'number' && Number.isFinite(value) && enumAccepts(rule, value);
236	    case 'integer':
237	      return typeof value === 'number' && Number.isInteger(value) && enumAccepts(rule, value);
238	    case 'array':
239	      return Array.isArray(value) && value.every((item) => accepts(rule.items as RuleJson, item));
240	    case 'object': {
241	      if (!isPlainJsonObject(value)) {
242	        return false;
243	      }
244	      const fields = rule.fields ?? {};
245	      for (const [name, fieldRule] of Object.entries(fields)) {
246	        const has = Object.prototype.hasOwnProperty.call(value, name);
247	        if (!has) {
248	          if (fieldRule.required === true) {
249	            return false;
250	          }
251	        } else if (!accepts(fieldRule, value[name])) {
252	          return false;
253	        }
254	      }
255	      if (rule.additionalProperties !== true) {
256	        for (const key of Object.keys(value)) {
257	          if (!Object.prototype.hasOwnProperty.call(fields, key)) {
258	            return false;
259	          }
260	        }
261	      }
262	      return true;
263	    }
264	    default:
265	      throw new Error(`参考实现遇到未知规则类型: ${JSON.stringify(rule.type)}`);
266	  }
267	}
268	
269	// ---------------------------------------------------------------------------
270	// 有限代表值域
271	// ---------------------------------------------------------------------------
272	//
273	// 设计目标：对本测试矩阵中的每一对（旧规则, 新规则），只要二者接受的 JSON
274	// 值集合不同，域中就存在一个见证值。为此域必须区分：
275	// - 整数与非整数（0/1 与 0.5）：区分 integer 与 number 的双向变化；
276	// - 字段缺失与 null（删除变体 与 显式 null）：区分“必填缺失”与“类型为 null”；
277	// - 空数组与非空数组（[] 与 [v]）：元素规则收紧在空数组上不可见；
278	// - 已声明字段与未声明额外字段（zz_extra）：区分 additionalProperties 两种策略；
279	// - 对象与数组的嵌套（递归到 MAX_DEPTH 层）。
280	//
281	// 构造方式（对每层对象规则）：
282	// - 标量代表值全集；
283	// - 空数组，以及元素代表值构成的单元素数组（若任一规则声明了数组元素规则，
284	//   元素域递归生成，否则用标量）；
285	// - 空对象、仅含额外字段的对象；
286	// - “基对象”：两规则声明字段的并集各取一个双方（退化为旧方）都接受的值，
287	//   再叠加额外字段；随后对每个字段做“删除”与“逐代表值替换”变体。
288	// 这样，新增必填字段由删除变体见证、字段类型收紧由替换变体见证、
289	// additionalProperties 收紧由叠加额外字段的对象见证、嵌套收紧由递归域见证。
290	//
291	// 注意：这只是针对本矩阵所测规则对的充分见证域，不构成对任意递归规则
292	// 包含关系的证明；矩阵中每条用例的期望都来自该域的穷举结果。
293	
294	const MAX_DEPTH = 2;
295	
296	// 标量代表值：覆盖 string（含空串）、整数、非整数、boolean、null
297	const SCALAR_REPS: readonly unknown[] = ['txt', '', 0, 1, 0.5, true, false, null];
298	
299	type FieldMap = { readonly [name: string]: RuleJson & { readonly required?: boolean } };
300	
301	function objectFields(rule: RuleJson | undefined): FieldMap {
302	  return rule !== undefined && rule.type === 'object' ? (rule.fields ?? {}) : {};
303	}
304	
305	function pickBase(
306	  subDomain: readonly unknown[],
307	  oldField: RuleJson | undefined,
308	  newField: RuleJson | undefined,
309	): unknown {
310	  const ok = (rule: RuleJson | undefined, v: unknown): boolean =>
311	    rule === undefined || accepts(rule, v);
312	  // 优先选双方规则都接受的值（基对象尽量是“好公民”），退化为旧规则接受，再退化为首元素
313	  return (
314	    subDomain.find((v) => ok(oldField, v) && ok(newField, v)) ??
315	    subDomain.find((v) => ok(oldField, v)) ??
316	    subDomain[0]
317	  );
318	}
319	
320	export function domainFor(
321	  oldRule: RuleJson | undefined,
322	  newRule: RuleJson | undefined,
323	  depth = 0,
324	): unknown[] {
325	  const values: unknown[] = [...SCALAR_REPS];
326	  if (depth >= MAX_DEPTH) {
327	    values.push([], {});
328	    return values;
329	  }
330	
331	  // 数组：空数组 + 元素代表值的单元素数组
332	  values.push([]);
333	  const itemOld = oldRule !== undefined && oldRule.type === 'array' ? oldRule.items : undefined;
334	  const itemNew = newRule !== undefined && newRule.type === 'array' ? newRule.items : undefined;
335	  const itemDomain =
336	    itemOld !== undefined || itemNew !== undefined
337	      ? domainFor(itemOld, itemNew, depth + 1)
338	      : SCALAR_REPS;
339	  for (const v of itemDomain) {
340	    values.push([v]);
341	  }
342	
343	  // 对象：空对象、额外字段对象、基对象及其删除/替换变体
344	  const fieldsOld = objectFields(oldRule);
345	  const fieldsNew = objectFields(newRule);
346	  const names = [...new Set([...Object.keys(fieldsOld), ...Object.keys(fieldsNew)])];
347	  let extra = 'zz_extra';
348	  while (names.includes(extra)) {
349	    extra = `${extra}_x`;
350	  }
351	  values.push({}, { [extra]: 0 }, { [extra]: 'txt' });
352	
353	  if (names.length > 0) {
354	    const subDomains = new Map<string, unknown[]>();
355	    const base: Record<string, unknown> = {};
356	    for (const name of names) {
357	      const sd = domainFor(fieldsOld[name], fieldsNew[name], depth + 1);
358	      subDomains.set(name, sd);
359	      base[name] = pickBase(sd, fieldsOld[name], fieldsNew[name]);
360	    }
361	    values.push(base, { ...base, [extra]: 0 }, { ...base, [extra]: 'txt' });
362	    for (const name of names) {
363	      const deleted = { ...base };
364	      delete deleted[name];
365	      values.push(deleted);
366	      for (const v of subDomains.get(name) as unknown[]) {
367	        if (!Object.is(v, base[name])) {
368	          values.push({ ...base, [name]: v });
369	        }
370	      }
371	    }
372	  }
373	
374	  return values;
