function buildAlignKeyMap(
  arr: readonly unknown[],
  keyField: string,
  arrayPointer: string,
): { readonly map: Map<string, AlignKeyEntry> } | { readonly problem: { readonly pointer: string; readonly reason: string } } {
  const map = new Map<string, AlignKeyEntry>();
  for (let i = 0; i < arr.length; i += 1) {
    const element = arr[i];
    const elementPointer = `${arrayPointer}/${i}`;
    if (!isPlainObject(element)) {
      return { problem: { pointer: elementPointer, reason: `对齐数组元素必须是对象，收到 ${jsonTypeOf(element)}` } };
    }
    if (!Object.prototype.hasOwnProperty.call(element, keyField)) {
      return { problem: { pointer: elementPointer, reason: `对齐数组元素缺少键字段 ${JSON.stringify(keyField)}` } };
    }
    const key = element[keyField] as unknown;
    const valid = typeof key === 'string' || typeof key === 'boolean' || (typeof key === 'number' && Number.isFinite(key));
    if (!valid) {
      return { problem: { pointer: `${elementPointer}/${escapePointerSegment(keyField)}`, reason: `对齐键必须是字符串、有限数字或布尔值（null 不能作键、不做类型转换），收到 ${jsonTypeOf(key)}` } };
    }
    const composite = alignCompositeKey(key as AlignKeyValue);
    const existing = map.get(composite);
    if (existing !== undefined) {
      return { problem: { pointer: elementPointer, reason: `对齐键 ${JSON.stringify(key)} 在同一数组内重复（另见下标 ${existing.index}）` } };
    }
    map.set(composite, { index: i, key: key as AlignKeyValue });
  }
  return { map };
}
