          `（键字段 ${JSON.stringify(spec.key)}）非法：正文位置 ${JSON.stringify(checked.problem.pointer)}：` +
          `${checked.problem.reason}\n`,
      );
      process.exit(2);
    }
    plannedKeys.set(spec.pointer, checked.keys);
  }
  return { endpoint, planned: parsed.value, plannedKeys };
});

