    { name: '键重复', plannedBody: '[{"id":1},{"id":1}]', expect: /重复/ },
  ];
  for (const c of bodyCases) {
    // 首条合法、末条非法：全部计划正文有效前不得连接，零请求
    const file = await writeText(
      dir,
      `bad-plan-${bodyCases.indexOf(c)}.json`,
      makeSnapshot([
        makeRecord(1, { target: '/api/items', plannedBody: '[{"id":1}]' }),
